L["Hide the breath bar"] = "Скрыть полосу дыхания"
L["Hides the breath bar and the game's other bars like it."] = "Скрывает полосу дыхания и другие похожие полосы игры."
L["Hide its text"] = "Скрыть текст"
L["Hides the word on the bar (Breath, Fatigue...), leaving the bar."] = "Скрывает слово на полосе (Дыхание, Усталость...), оставляя саму полосу."
L["The bar's fill texture."] = "Текстура заливки полосы."
L["The font of the word on the bar. (In Russian, Korean and Chinese it stays the game's.)"] = "Шрифт слова на полосе. (В русском, корейском и китайском остается игровой.)"
L["Which swing timer bars show."] = "Какие полосы таймера удара видны."
