L["How long a bar stays after you stop attacking."] = "Сколько полоса остается после прекращения атаки."
L["Puts the ranged bar on top for this class."] = "Ставит полосу дальнего боя сверху для этого класса."
L["CineMode hides the Cooldown Manager: pick when it shows."] = "CineMode скрывает менеджер восстановления: выберите, когда его показывать."
L["Turns this page's Cooldown Manager settings on or off."] = "Включает или выключает настройки менеджера восстановления на этой странице."
L["CDM"] = "МВ"
L["Each bar's and spell's icons: when they show, numbers, keybinds and more."] = "Значки каждой полосы и заклинания: когда видны, числа, клавиши и прочее."
L["Smart set, and how icons flash when a cooldown ends."] = "Умная настройка и вспышка значков по окончании восстановления."
L["Cooldown Settings"] = "Настройки восстановления"
L["Open CDM"] = "Открыть МВ"
L["Opens the game's own Cooldown Manager settings."] = "Открывает собственные настройки менеджера восстановления игры."
L["Sets every spell in this group to this."] = "Задает это всем заклинаниям группы."
L["When this buff's icon or bar shows."] = "Когда видны значок или полоса этого баффа."
