L["Game's option (on)"] = "Настройка игры (вкл.)"
L["Game's option (off)"] = "Настройка игры (выкл.)"
L["Numbers"] = "Числа"
L["Countdown numbers on the icons."] = "Числа отсчета на значках."
L["Left to the game"] = "На усмотрение игры"
L["Each spell's keybind on its icon."] = "Клавиша каждого заклинания на его значке."
L["Use the spell's cooldown, not its buff"] = "Восстановление, а не бафф"
L["Shows the spell's own cooldown instead of its buff or DoT."] = "Показывает восстановление самого заклинания вместо его баффа или периодического урона."
L["Same as bar (%s)"] = "Как у полосы (%s)"
L["Closes the gaps so the shown buffs sit centered."] = "Убирает промежутки, чтобы видимые баффы были по центру."
L["Closes the gaps so the shown icons sit centered."] = "Убирает промежутки, чтобы видимые значки были по центру."
L["Keeps the Cooldown Manager up until every cooldown in this bar is ready."] = "Держит менеджер восстановления, пока все способности этой полосы не будут готовы."
L["Stacks and time left"] = "Заряды и остаток"
L["Shows stacks and time left on tracked buff icons."] = "Показывает заряды и оставшееся время на значках отслеживаемых баффов."
L["Click for this bar's own settings."] = "Щелкните для собственных настроек полосы."
L["Click for this spell's own settings."] = "Щелкните для собственных настроек заклинания."
L["Sets spells you haven't set yourself based on what they cost."] = "Настраивает не заданные вами заклинания по их стоимости."
L["Resets every icon setting to the active profile's."] = "Сбрасывает все настройки значков к активному профилю."
L["Highlights mobs, NPCs and objects you still need for a quest."] = "Подсвечивает существ, НИП и объекты, которые еще нужны для задания."
L["Turns Quest Vision on or off."] = "Включает или выключает Quest Vision."
L["What shows of mobs and NPCs you still need for a quest."] = "Что видно у существ и НИП, которые еще нужны для задания."
L["Shows a gold ! beside the nameplates of quest mobs and NPCs."] = "Показывает золотой ! рядом с индикаторами существ и НИП для заданий."
L["Cinematic's wins"] = "Важнее Cinematic"
L["Questie's wins"] = "Важнее Questie"
L["Both show"] = "Видны оба"
L["Which quest icon shows when both Cinematic and Questie mark the same unit."] = "Какой значок задания показывать, когда Cinematic и Questie отмечают одного юнита."
L["Questie's icons"] = "Значки Questie"
L["The quest mark on friendly NPCs; click to pick another."] = "Знак задания на дружественных НИП; щелкните, чтобы выбрать другой."
L["The quest mark on enemies; click to pick another."] = "Знак задания на врагах; щелкните, чтобы выбрать другой."
L["A big button for the nearest tracked quest's usable item."] = "Большая кнопка для используемого предмета ближайшего отслеживаемого задания."
L["Fade if another addon competes"] = "Скрывать при конкуренции"
L["Hides this button when another addon shows one for the same item."] = "Скрывает эту кнопку, когда другой аддон показывает свою для того же предмета."
L["The quest object in front of you glows gold."] = "Объект задания перед вами светится золотом."
L["Hide object icons"] = "Скрыть значки объектов"
L["Hides the game's icon on the object your interact key would use."] = "Скрывает значок игры на объекте, с которым взаимодействует клавиша взаимодействия."
L["Closes talking heads you've already seen."] = "Закрывает уже виденные говорящие головы."
L["NPC dialogue shows in a speech bubble and reply list instead of the game's windows."] = "Диалоги НИП показываются в облачке и списке ответов вместо окон игры."
L["Hides Cinematic's dialogue when another dialogue addon is running."] = "Скрывает диалоги Cinematic, когда работает другой аддон диалогов."
L["Game's window with a controller"] = "Окно игры с геймпадом"
L["Uses the game's own dialogue windows in gamepad mode."] = "В режиме геймпада использует окна диалогов игры."
L["Where the speech bubble goes."] = "Где располагается облачко речи."
L["How far the bubble stays from the top of the screen."] = "Насколько облачко отстоит от верха экрана."
L["Stops the camera drifting while you talk."] = "Останавливает дрейф камеры во время разговора."
L["What the bubble and card do while the camera moves."] = "Что делают облачко и карточка, пока камера движется."
L["The shop window opens where the talk was."] = "Окно торговли открывается на месте разговора."
L["Shows group loot rolls in a window instead of only in chat."] = "Показывает розыгрыш добычи группы в окне, а не только в чате."
L["Party/Dungeon"] = "Группа/подземелье"
L["The rules while you're in a party: in a dungeon, a delve or out in the world."] = "Правила, пока вы в группе: в подземелье, вылазке или в открытом мире."
L["The rules while you're in a raid group."] = "Правила, пока вы в рейдовой группе."
L["No panel; rolls show only in chat."] = "Без панели; броски только в чате."
L["Shows a panel with the winner once the item's won."] = "Показывает панель с победителем, когда предмет разыгран."
L["All Rolls"] = "Все броски"
L["Whether items of this quality get a panel in the window."] = "Получают ли предметы этого качества панель в окне."
L["Usable"] = "Пригодные"
L["Only items you can use get a panel."] = "Панель только для предметов, которые вы можете использовать."
L["Hide Uncounted"] = "Скрыть неучтенные"
L["Hides Greed and Transmog rolls once someone rolls Need."] = "Скрывает броски «Не откажусь» и «Трансмогрификация», когда кто-то выбрал «Нужно»."
L["Max Players"] = "Макс. игроков"
L["Each item lists at most this many players' rolls; click its panel to see everyone."] = "У каждого предмета не больше стольких бросков; щелкните по панели, чтобы увидеть всех."
L["Separate window"] = "Отдельное окно"
L["Where the roll window shows: beside the game's roll frames or as its own window."] = "Где показывается окно розыгрыша: рядом с рамками розыгрыша игры или отдельным окном."
L["Popup location"] = "Место окна"
L["How many items the window shows at once; the oldest goes when a new one drops."] = "Сколько предметов окно показывает сразу; при новой добыче самый старый уходит."
