L["The member under your mouse shows at least this much; 0% turns it off."] = "Участник под курсором виден хотя бы настолько; 0% — выключено."
L["How much of offline members still shows."] = "Насколько видны участники не в сети."
L["How much of members out of your healing range still shows."] = "Насколько видны участники вне радиуса исцеления."
