L["Hover over frames, then click Stop to add them to the list."] = "Наведите курсор на рамки, затем нажмите «Стоп», чтобы добавить их в список."
L["Type part of a frame's or addon's name to find it."] = "Введите часть имени рамки или аддона, чтобы найти."
L["Turns CineMode on or off."] = "Включает или выключает CineMode."
L["Hides the whole UI but keeps the CineMode effects."] = "Скрывает весь интерфейс, сохраняя эффекты CineMode."
L["Takes a screenshot with the UI hidden."] = "Делает снимок экрана со скрытым интерфейсом."
L["Turns the visual effects on or off."] = "Включает или выключает визуальные эффекты."
L["Shows or hides the letterbox bars."] = "Показывает или скрывает полосы кадра."
L["Hides the cursor until you move the mouse."] = "Скрывает курсор, пока вы не сдвинете мышь."
L["Reloads the UI."] = "Перезагружает интерфейс."
L["Opens or closes Cinematic's settings."] = "Открывает или закрывает настройки Cinematic."
