L["Hold to open a wheel of raid target markers."] = "Удерживайте, чтобы открыть колесо меток целей рейда."
L["Hold to open a wheel of ground markers; only in a group."] = "Удерживайте, чтобы открыть колесо меток на земле; только в группе."
L["Hold to open a wheel that turns the visions on or off."] = "Удерживайте, чтобы открыть колесо включения и выключения Visions."
L["Turns Damage Vision on or off (its Enable Page switch)."] = "Включает или выключает Damage Vision (переключатель «Включить страницу»)."
L["Turns Teleport Vision on or off (its Enable Page switch)."] = "Включает или выключает Teleport Vision (переключатель «Включить страницу»)."
L["Turns Emote Vision on or off (its Enable Page switch)."] = "Включает или выключает Emote Vision (переключатель «Включить страницу»)."
L["Turns Card Vision on or off (its Enable Page switch)."] = "Включает или выключает Card Vision (переключатель «Включить страницу»)."
L["Starts the AFK camera now."] = "Запускает АФК-камеру сейчас."
L["Starts the cozy camera now."] = "Запускает уютную камеру сейчас."
L["Starts the vista camera now."] = "Запускает панорамную камеру сейчас."
L["Starts the fish camera now."] = "Запускает камеру рыбалки сейчас."
L["Starts the tele camera now."] = "Запускает камеру телепорта сейчас."
L["Starts or stops the RP walk camera."] = "Запускает или останавливает камеру РП-шага."
L["Starts or stops the auto-run camera."] = "Запускает или останавливает камеру автобега."
L["Pretends you're dead for 30 seconds to test the death camera."] = "Изображает вашу смерть на 30 секунд для проверки камеры смерти."
L["Turns the Shoulder Cam on or off (its Enable Page switch)."] = "Включает или выключает Камеру через плечо (переключатель «Включить страницу»)."
L["Stops whichever of Cinematic's cameras is running now, however it started."] = "Останавливает работающую сейчас камеру Cinematic, как бы она ни запустилась."
L["Targets the last NPC who spoke near you."] = "Берет в цель последнего НИП, говорившего рядом."
L["Scene keys"] = "Клавиши сцен"
L["Plays your scenes that use this key."] = "Запускает ваши сцены с этой клавишей."
L["Hold to see tooltips that are hidden."] = "Удерживайте, чтобы видеть скрытые подсказки."
L["hidden"] = "скрыто"
L["Click, then press a key; right-click to clear."] = "Щелкните, затем нажмите клавишу; ПКМ — очистить."
L["Keys for Cinematic, the same as in the game's Key Bindings under AddOns."] = "Клавиши Cinematic, те же, что в «Назначении клавиш» игры в разделе «Модификации»."
L["Key groups"] = "Группы клавиш"
L["New key group"] = "Новая группа клавиш"
L["A key group of your own: name it, set its key and pick its frames."] = "Ваша группа клавиш: назовите ее, задайте клавишу и выберите рамки."
L["Deletes this group and its keys."] = "Удаляет эту группу и ее клавиши."
L["Pick the frames this group's key shows and hides."] = "Выберите рамки, которые показывает и скрывает клавиша группы."
L["Key group %d"] = "Группа клавиш %d"
L["No frames yet: pick them on the right"] = "Рамок пока нет: выберите их справа"
L["Pick frames (%d)"] = "Выбрать рамки (%d)"
L["Reset frame keys after a reload"] = "Сбрасывать клавиши рамок после перезагрузки"
L["Frames you showed or hid with their keys go back to normal after a reload."] = "Рамки, показанные или скрытые клавишами, после перезагрузки возвращаются в обычное состояние."
L["Back to their Show in rows"] = "Вернуть к строкам «Показ в»"
L["A profile is a whole set of settings you can switch between."] = "Профиль — это полный набор настроек, между которыми можно переключаться."
L["Pick, add and share profiles."] = "Выбирайте, добавляйте и передавайте профили."
L["Change parts of the active profile."] = "Изменяйте части активного профиля."
L["This character keeps its own profile."] = "У этого персонажа свой профиль."
L["Makes a copy of the active profile as your own."] = "Создает копию активного профиля как ваш собственный."
L["Brings back an older copy of a profile."] = "Возвращает старую копию профиля."
L["Adds a profile someone shared with you."] = "Добавляет профиль, которым с вами поделились."
L["Gives you the active profile as text to share."] = "Дает активный профиль в виде текста, чтобы поделиться."
L["Write what the active profile is for."] = "Напишите, для чего активный профиль."
L["Puts the active profile back to how you last saved it."] = "Возвращает активный профиль к последнему сохранению."
L["Saves the active profile as the point Reset goes back to."] = "Сохраняет активный профиль как точку, к которой возвращает «Сброс»."
L["Your own profile."] = "Ваш собственный профиль."
L["Customizing %s"] = "Настройка: %s"
L["Customize %s"] = "Настроить: %s"
L["Frames in the same group come up together when you mouse over any of them."] = "Рамки одной группы появляются вместе при наведении на любую из них."
L["How long a frame stays after your mouse leaves it."] = "Сколько рамка остается после ухода курсора."
L["All parts"] = "Все части"
L["%s (all parts)"] = "%s (все части)"
L["%s (%d of %d parts)"] = "%s (%d из %d частей)"
L["Which parts of this frame come up with this group."] = "Какие части рамки появляются с этой группой."
L["When this group works: any time, in combat or out of combat."] = "Когда работает группа: всегда, в бою или вне боя."
L["Turns this group on or off."] = "Включает или выключает эту группу."
L["Hover reach"] = "Радиус наведения"
L["%d px"] = "%d пикс."
L["How close the mouse must come to this group's buttons to bring it up."] = "Насколько близко курсор должен подойти к кнопкам группы, чтобы она появилась."

