L["Records the addon's CPU use while you play; click again to stop."] = "Записывает нагрузку аддона на процессор во время игры; щелкните снова, чтобы остановить."
L["Times nearly every function too, which makes everything read a bit higher."] = "Замеряет также почти каждую функцию, из-за чего все показатели чуть выше."
L["Starts recording right away instead of when you close the settings."] = "Начинает запись сразу, а не при закрытии настроек."
L["Copies a text report to send us."] = "Копирует текстовый отчет, чтобы прислать нам."

