-- Options.lua
L["Pick Always, < 100%, < 100% Calm or Off, or scroll over the box for other percentages."] = "Выберите «Всегда», «< 100%», «< 100% затишье» или «Выкл.», или крутите колесо над полем для других процентов."
L["Pick Always, < 100% or Off, or scroll over the box for other percentages."] = "Выберите «Всегда», «< 100%» или «Выкл.», или крутите колесо над полем для других процентов."
L["Turns this page on or off, same as right-clicking its icon."] = "Включает или выключает эту страницу, как ПКМ по ее значку."
L["Put this page's settings back to your profile's defaults?"] = "Вернуть настройки этой страницы к значениям по умолчанию вашего профиля?"
L["Put these settings back to your profile's defaults?"] = "Вернуть эти настройки к значениям по умолчанию вашего профиля?"
L["|cff808080Searching...|r"] = "|cff808080Поиск...|r"
L["Allow offscreen nameplates in CineMode"] = "Индикаторы за экраном в CineMode"
L["Keeps plates for people behind you, so Heal Vision and Emote Vision see them too."] = "Сохраняет индикаторы тех, кто у вас за спиной, чтобы Heal Vision и Emote Vision их тоже видели."
L["Only where Heal Vision or Emote Vision use them."] = "Только там, где они нужны Heal Vision или Emote Vision."
L["All through CineMode."] = "Все время в CineMode."
L["Cinematic never turns them on."] = "Cinematic никогда их не включает."
L["CineMode turns on by itself between fights and fades the UI."] = "CineMode сам включается между боями и скрывает интерфейс."
L["Walking or riding around brings the UI back."] = "Если пойти или поехать, интерфейс вернется."
L["Use a Show in row instead"] = "Вместо этого строка «Показ в»"
L["The row below picks where CineMode exits, in place of the boxes above."] = "Строка ниже решает, где выходить из CineMode, вместо отметок выше."
L["Keeps CineMode off everywhere."] = "CineMode выключен везде."
L["Sweeps turn the other way."] = "Повороты идут в другую сторону."
L["Each time, the camera picks clockwise or counterclockwise at random."] = "Каждый раз камера сама случайно выбирает: по часовой стрелке или против."
L["Put this camera's settings back to your profile's defaults?"] = "Вернуть настройки этой камеры к значениям по умолчанию вашего профиля?"
L["Now and then the camera turns around to look back past you."] = "Время от времени камера разворачивается и оглядывается назад мимо вас."
L["How far the camera turns around, where 180 looks straight back at you."] = "Насколько камера разворачивается; при 180 она смотрит прямо на вас."
L["How long the turn around takes, speeding up and slowing down."] = "Сколько длится разворот, с разгоном и замедлением."
L["As you land, the camera zooms back to the zoom you had at takeoff."] = "Когда вы приземляетесь, камера возвращается к приближению, которое было на взлете."
L["The camera sways slowly from side to side around where it started, pausing between moves."] = "Камера медленно покачивается из стороны в сторону вокруг начальной точки, с паузами."
L["Once it has turned halfway around, the camera sways slowly from side to side."] = "Повернувшись наполовину, камера медленно покачивается из стороны в сторону."
L["When you /stare at the view, the camera sways very slightly from where it is."] = "Когда вы любуетесь видом через /stare, камера чуть-чуть покачивается на месте."
L["The camera sways very slightly from side to side."] = "Камера чуть-чуть покачивается из стороны в сторону."
L["While you fish, the camera sways a little and keeps your bobber in view."] = "Пока вы рыбачите, камера слегка покачивается и не упускает поплавок из вида."
L["While you auto-walk, the camera drifts slowly along with you."] = "Во время автоходьбы камера медленно плывет вместе с вами."
L["Each death, the camera picks clockwise or counterclockwise at random."] = "При каждой смерти камера случайно выбирает: по часовой стрелке или против."
L["The camera zooms in to this distance if you're farther out."] = "Если камера дальше, она приближается до этого расстояния."
L["Which side of you the camera moves to."] = "С какой стороны от вас встает камера."
L["The camera turns to the side as it zooms in, then tilts down."] = "Приближаясь, камера поворачивается вбок, а потом наклоняется вниз."
L["How fast the spin speeds up after the first half turn."] = "Как быстро вращение ускоряется после первого полуоборота."
L["As it turns, the camera also drops toward the ground. Negative values raise it instead."] = "Поворачиваясь, камера еще и опускается к земле. Отрицательные значения ее поднимают."
L["The camera starts zooming in when the cast starts, and is still zooming in as you leave."] = "Камера начинает приближаться с началом заклинания и все еще приближается, когда вы исчезаете."
L["How fast the camera zooms back out to your own distance if you cancel the cast."] = "Как быстро камера отъезжает обратно на ваше расстояние, если вы отмените заклинание."
L["Load Atmosphere"] = "Загружать Атмосферу"
L["Unticked, Atmosphere doesn't load at all (takes a reload)."] = "Без отметки Атмосфера не загружается совсем (нужна перезагрузка)."
L["Tick it and reload to bring every Atmosphere page back."] = "Отметьте и перезагрузитесь, чтобы вернуть все страницы Атмосферы."
L["Turn off to keep Atmosphere from loading at all."] = "Выключите, чтобы Атмосфера не загружалась совсем."
L["Atmosphere isn't loaded: no tint, letterbox, haze, Graphics Boost or music runs, and their pages are gone."] = "Атмосфера не загружена: оттенок, полосы, дымка, улучшение графики и музыка не работают, их страниц нет."
L["How the game world looks in CineMode: vignette, inn glow and depth of field."] = "Как выглядит игровой мир в CineMode: виньетка, свет в тавернах и глубина резкости."
L["Haze"] = "Дымка"
L["Darkens the edges of the screen."] = "Затемняет края экрана."
L["Shows the vignette for a few seconds, in CineMode or not."] = "Показывает виньетку на несколько секунд, в CineMode или без него."
L["A warm firelight glow, brightest low on the screen."] = "Теплый свет очага, ярче всего внизу экрана."
L["Shows the glow for a few seconds, in CineMode or not."] = "Показывает свет на несколько секунд, в CineMode или без него."
L["Haze strength"] = "Сила дымки"
L["A light haze around the edges of the screen."] = "Легкая дымка по краям экрана."
L["Shows the haze at this strength for a few seconds, in CineMode or not."] = "Показывает дымку такой силы на несколько секунд, в CineMode или без него."
L["How they look"] = "Как они выглядят"
L["Style pages:"] = "Страницы стиля:"
L["The tint's preset, time of day and zone moods."] = "Набор оттенка, время суток и настроение зон."
L["Each weather's color, and how fast it comes in."] = "Цвет каждой погоды и как быстро она наступает."
L["Music can play any time in CineMode, so the other columns don't matter."] = "Музыка может играть в CineMode когда угодно, так что остальные столбцы не важны."
L["Load Cameras"] = "Загружать камеры"
L["Unticked, Cinematic's cameras don't load at all (takes a reload)."] = "Без отметки камеры Cinematic не загружаются совсем (нужна перезагрузка)."
L["Tick it and reload to bring every camera back."] = "Отметьте и перезагрузитесь, чтобы вернуть все камеры."
L["Turn off to keep the cameras from loading at all."] = "Выключите, чтобы камеры не загружались совсем."
L["Cameras aren't loaded: none of them run, and their pages are gone."] = "Камеры не загружены: ни одна не работает, их страниц нет."
L["In CineMode, the camera moves on its own when things happen, like emotes, flights or going AFK."] = "В CineMode камера сама двигается, когда что-то происходит: эмоции, полеты, уход в АФК."
L["Move this row up so its trigger tries it sooner."] = "Поднимите строку, чтобы триггер пробовал ее раньше."
L["Move this row down so its trigger tries it later."] = "Опустите строку, чтобы триггер пробовал ее позже."
L["Uses this row. Untick it and its trigger skips it."] = "Строка используется. Снимите отметку, и триггер ее пропустит."
L["Turns this section on or off. When it's off, CineMode leaves its frames alone."] = "Включает или выключает этот раздел. Когда он выключен, CineMode не трогает его рамки."
L["CineMode hides the range hint: pick when it shows."] = "CineMode скрывает подсказку дальности: выберите, когда ее показывать."
L["When the XP bar, bags, micro menu and similar frames show."] = "Когда показываются полоса опыта, сумки, микроменю и похожие рамки."
L["How the damage and healing numbers over heads look."] = "Как выглядят цифры урона и исцеления над головами."
L["Shows chat bubbles where this page says. When it's off, the game's own settings are used."] = "Показывает облачка чата там, где указано на этой странице. Когда она выключена, действуют настройки игры."
L["Windows"] = "Окна"
L["Open windows clear of your character"] = "Окна не заслоняют персонажа"
L["Dead center instead"] = "Лучше строго по центру"
L["Opens them in the very middle of the screen."] = "Открывает их точно посередине экрана."
L["Forget where you dragged the windows, so each opens in its usual place again."] = "Забыть, куда вы перетащили окна, чтобы каждое снова открывалось на обычном месте."
L["Dressing room beside the Auction House"] = "Примерочная рядом с аукционом"
L["Ctrl+Click an auction to see it on you without the Auction House closing."] = "Ctrl+клик по лоту — примерить его, не закрывая аукцион."
L["Gear and talents"] = "Экипировка и таланты"
L["Off by default because it can cause harmless errors in error-catching addons."] = "По умолчанию выключено: может вызывать безобидные ошибки в модификациях, которые ловят ошибки."
L["Login and reload"] = "Вход и перезагрузка"
L["Open the AddOns list on All"] = "Список модификаций на «Все»"
L["The game's AddOns list starts on All instead of just this character."] = "Список модификаций игры открывается на «Все», а не только на этом персонаже."
L["Text on screen"] = "Текст на экране"
L["Cast and reel in with the mouse or a gamepad, in CineMode or not."] = "Забрасывайте и подсекайте мышью или геймпадом, в CineMode или без него."
L["The game's sound effects volume while you fish. The splash of a bite is a sound effect."] = "Громкость звуковых эффектов игры, пока вы рыбачите. Всплеск поклевки — это звуковой эффект."
L["Show in fights, and after them until the Calm Timer runs out."] = "Показывать в бою и после него, пока не истечет таймер затишья."
L["Show in fights while you're PvP flagged, and after them until the Calm Timer runs out."] = "Показывать в бою в режиме PvP и после него, пока не истечет таймер затишья."
L["Show out in the world, inns included. Capital cities count as Cities."] = "Показывать в открытом мире, и в тавернах тоже. Столицы считаются «Городами»."
L["Enemies in ~30 yd"] = "Враги в ~30 м"
L[" The nameplate of the unit under your mouse, whatever the Nameplates grid says."] = " Индикатор того, кто под курсором, что бы ни говорила сетка «Индикаторы»."
L[" Hostile NPCs and enemy players within about 30 yards (your spell nearest 30 yards), whatever their rows say."] = " Враждебные НИП и вражеские игроки примерно в 30 м (по вашему заклинанию, ближайшему к 30 м), что бы ни говорили их строки."
L[" The glow when a mob is targeting you or about to."] = " Свечение, когда противник выбрал вас целью или вот-вот выберет."
L["Far, behind walls"] = "Далеко, за стенами"
L["%d%%"] = "%d%%"
L["Past 28 yards, how much of a title still shows when the game thinks it's behind a wall. 0 hides it."] = "Дальше 28 м: насколько виден титул, когда игра считает, что он за стеной. 0 скрывает его."
L["Mouseover nameplates"] = "Индикатор под курсором"
L["Target names"] = "Имя цели"
L[" The name of the unit under your mouse, even with its kind's names off."] = " Имя того, кто под курсором, даже если имена его типа выключены."
L["All names"] = "Все имена"
L[" Every other names row shows only where this one does."] = " Все остальные строки имен работают только там, где работает эта."
L["Names look as this page says. When it's off, they look the way the nameplate draws them."] = "Имена выглядят так, как задано на этой странице. Когда она выключена — так, как их рисует индикатор."
L["Every plate that no row above fits."] = "Все индикаторы, которым не подошла ни одна строка выше."
L["How every nameplate looks: its bar, its name and its parts."] = "Как выглядит каждый индикатор: полоса, имя и остальные части."
L["Turns the nameplates' look on or off, Smart, Cast Bars and Layout with it."] = "Включает или выключает вид индикаторов, а с ним «Умный», полосы заклинаний и макет."
L["Limits this row to the enemies among them."] = "Только враги из них."
L["Limits this row to the neutral ones among them."] = "Только нейтральные из них."
L["Limits this row to the friendly ones among them."] = "Только дружественные из них."
