L["Tick Enemy, Neutral or Friendly to limit this row to those. Tick all three for any."] = "Отметьте «Враг», «Нейтральный» или «Дружественный», чтобы оставить в строке только их. Все три — любые."
L["can't measure"] = "нечем измерить"
L["Nothing on this character measures distance."] = "У этого персонажа нечем измерить расстояние."
L["Measured with %s (%d yards)."] = "Измеряется по: %s (%d м)."
L["In fights: %s (%d yards)."] = "В бою: %s (%d м)."
L["In fights nothing measures it."] = "В бою измерить нечем."
L["Pop out: this row's preview in a window of its own."] = "Открепить: предпросмотр этой строки в отдельном окне."
L["This row's own look on its plates, in the Style Studio."] = "Собственный вид индикаторов этой строки, в Студии стиля."
L["Tick the parts of the plate that get its color."] = "Отметьте части индикатора, которые получат этот цвет."
L["Its messages show chat out in the world, inns included. Capital cities count as Cities."] = "Его сообщения показывают чат в открытом мире, и в тавернах тоже. Столицы считаются «Городами»."
L["When a new message shows chat, and which parts of the chat window come up with it."] = "Когда новое сообщение показывает чат и какие части окна чата появляются вместе с ним."
L["Pressing Enter brings up the chat window where ticked, and just the input box elsewhere."] = "Enter открывает окно чата там, где отмечено, а в остальных местах — только поле ввода."
L["Typing brings up the chat window any time, so the other columns don't matter."] = "Когда вы печатаете, окно чата появляется всегда, так что остальные столбцы не важны."
L["Where and when the minimap stays up the whole time."] = "Где и когда миникарта остается на экране все время."
L["Shows the minimap while the spot to hand in a finished quest is on it."] = "Показывает миникарту, пока на ней видно место сдачи выполненного задания."
L["Map pin"] = "Метка на карте"
L["Shows the minimap while your map pin is on it."] = "Показывает миникарту, пока на ней видна ваша метка."
L["Not for Shortest Path"] = "Кроме Shortest Path"
L["Shortest Path Forever's journey pin doesn't show the minimap."] = "Метка маршрута Shortest Path Forever не показывает миникарту."
L["How long the minimap stays up after quest progress. Set to Off to keep it up."] = "Сколько миникарта держится после продвижения задания. «Выкл.» — держать все время."
L["Takes effect after a reload."] = "Сработает после перезагрузки."
L["Load Style"] = "Загружать Стиль"
L["Unticked, Style doesn't load at all (takes a reload)."] = "Без отметки Стиль не загружается совсем (нужна перезагрузка)."
