L["Spell for %s"] = "Заклинание для %s"
L["The mark shows while your target is out of this spell's range. Auto uses the longest-range attack on your bars."] = "Метка видна, пока цель дальше, чем достает это заклинание. «Авто» берет атаку с самой большой дальностью с ваших панелей."
