L["Closes the game's own Cooldown Manager settings."] = "Закрывает настройки менеджера восстановления игры."
L["Essentials"] = "Основные"
L["Set here but never takes effect:"] = "Задано здесь, но не действует:"
L["%s in %s (no locations yet)"] = "%s в %s (мест пока нет)"
L["%s in %s (never applies)"] = "%s в %s (не действует)"
L["Spells with Flash set flash as their cooldown ends. Off: none do."] = "Заклинания с «Вспышкой» мигают, когда восстанавливаются. «Выкл.»: не мигает ни одно."
L["The icon grows a little and shrinks back with each beat while it flashes."] = "Пока значок мигает, он с каждым ударом чуть увеличивается и сжимается обратно."
L[" You can change its look on the Quest Item Button tab."] = " Его вид можно поменять на вкладке «Кнопка предмета задания»."
L["Works in"] = "Работает в"
L["On in fights, and after them until the Calm Timer runs out."] = "Включено в бою и после него, пока не истечет таймер затишья."
L["On while you're in any of these. Party and Raid count anywhere, as long as you're in one."] = "Включено, пока вы в любом из этих мест. «Группа» и «Рейд» работают везде, пока вы в группе или рейде."
L["These settings apply to every role that uses the default settings."] = "Эти настройки действуют для всех ролей, у которых настройки по умолчанию."
L["How much of a dead member still shows."] = "Насколько виден погибший участник."
L["Hidden members still show their aura icons and dispel glow."] = "У скрытых участников все равно видны значки аур и свечение рассеивания."
L["Show health on names"] = "Здоровье на именах"
L["Names grey out as health is lost, like a health bar."] = "Имена сереют по мере потери здоровья, как полоса здоровья."
L["Tooltips show the whole time in CineMode, so the other columns don't matter."] = "Подсказки видны в CineMode все время, так что остальные столбцы не важны."
L["The zone under a party member's class when they're out of sight (\"Stormwind City\")."] = "Зона под классом участника группы, когда его не видно (\"Штормград\")."
L["Faction and PvP (yours)"] = "Фракция и PvP (ваши)"
L["The Horde or Alliance and PvP lines of your own faction."] = "Строки «Орда» или «Альянс» и PvP у вашей фракции."
L["Faction and PvP (enemies)"] = "Фракция и PvP (враги)"
L["The Horde or Alliance and PvP lines of the other faction."] = "Строки «Орда» или «Альянс» и PvP у другой фракции."
L["CineMode hides these addons' frames. Pick which ones show, and when."] = "CineMode скрывает рамки этих модификаций. Выберите, какие показывать и когда."
L["Addons you install later always show in CineMode to start with."] = "Модификации, которые вы поставите позже, поначалу всегда видны в CineMode."
L["Does what Load does for every frame on this list that isn't loaded yet."] = "Делает то же, что «Загрузить», для каждой еще не загруженной рамки в списке."
L["Frames you've shown or hidden with their keys below go back to what their Show in row says."] = "Рамки, которые вы показали или скрыли клавишами ниже, снова слушаются своей строки «Показ в»."
L["Cinematic's page comes up when the fight ends"] = "Страница Cinematic откроется после боя"
L["Put the profile %s back to how it started? Every change you've made to it will be lost."] = "Вернуть профиль %s к исходному виду? Все ваши изменения в нем пропадут."
L["Put the profile %s back to how you last saved it? Changes you've made since then will be lost."] = "Вернуть профиль %s к последнему сохранению? Изменения после него пропадут."
L["Pointing at a faded frame shows it, along with the other frames in its groups."] = "Если навести курсор на скрытую рамку, она появится вместе с другими рамками своих групп."
L["Right-click to go back to its own icon."] = "ПКМ — вернуть его собственный значок."
L["Floating text changes after you log out and back in (/reload isn't enough). The same goes for getting it back: until you log out it stays hidden, even with Cinematic turned off."] = "Всплывающий текст меняется только после перезахода в игру (/reload не хватит). Чтобы вернуть его, тоже: пока вы не выйдете, он остается скрытым, даже с выключенным Cinematic."
L["Style isn't loaded: no Style page or look runs, and their pages are gone."] = "Стиль не загружен: ни одна страница и ни один вид Стиля не работают, их страниц нет."

-- ProfilerPage.lua
L["It's off. Right-click the Profiler icon to start sampling."] = "Он выключен. Нажмите ПКМ на значке профилировщика, чтобы начать замеры."
L["What the game measured for Cinematic over the same time, including what the timers don't cover."] = "Что игра намерила для Cinematic за то же время, включая то, чего не видят таймеры."
L["Memory used and thrown away each second. The game spends time cleaning it up."] = "Сколько памяти занято и выброшено за секунду. Игра тратит время на ее уборку."
L["(Called by the part above, so its time is counted in that one.)"] = "(Вызывается частью выше, поэтому ее время входит в ту.)"

-- RuleAxes.lua
L["open now"] = "открыто сейчас"

-- Slash.lua
L["the camera turns once around you: 360 degrees over 10 seconds unless you give a number (a negative one turns the other way); again stops it"] = "камера делает один круг вокруг вас: 360 градусов за 10 секунд, если не указать число (отрицательное — в другую сторону); повтор останавливает"
L["show or hide the keyboard map: what each of your keys does (add words to find them on it)"] = "показать или скрыть карту клавиш: что делает каждая ваша клавиша (добавьте слова, чтобы найти их на ней)"
L["fade the frame you're hovering over too (or /cine add <FrameName>)"] = "скрывать еще и рамку под курсором (или /cine add <ИмяРамки>)"
L["your damage report for this run: boss by boss, the rest, the whole party (test shows a made-up one)"] = "ваш отчет об уроне за этот забег: по каждому боссу, остальное, вся группа (test покажет выдуманный)"
L["record what the addon costs, results on the Profiler page (add deep for more detail, or stop to end it early)"] = "записать, сколько ресурсов ест модификация, итог на странице «Профилировщик» (добавьте deep для подробностей или stop, чтобы закончить раньше)"
L["%d matches for \"%s\", best: \"%s\" (%s). Pick one in the results window."] = "Найдено %d для \"%s\", лучшее: \"%s\" (%s). Выберите нужное в окне результатов."
L["That needs %s, which you've left out (its General page's Load box)."] = "Для этого нужен модуль %s, а вы его отключили (отметка «Загрузить» на его странице «Общие»)."

