L["letterbox bars: the Letterbox page is off"] = "полосы кадра: страница «Полосы» выключена"

-- Atmosphere/LowHealth.lua
L["That isn't the whole thing. Copy it again, all of it."] = "Это не целиком. Скопируйте еще раз, полностью."
L["At what health the edges close in, and how fast."] = "При каком здоровье края сжимаются и как быстро."
L["The color of a big hit's flash, and the color the world fades to."] = "Цвет вспышки при сильном ударе и цвет, в который уходит мир."
L["This theme's heartbeat speed, relative to Beats a minute above. A creeping theme beats slower."] = "Скорость сердцебиения этой темы относительно «Ударов в минуту» выше. У ползучей темы сердце бьется медленнее."
L["How much this theme throbs, relative to Throb above."] = "Насколько пульсирует эта тема относительно «Пульсации» выше."
L["The theme's art that spreads in from the edges."] = "Изображение темы, которое наползает с краев."
L["The glow around the art, added as light. This is Glow's only color."] = "Свечение вокруг изображения, добавляется как свет. Это единственный цвет «Свечения»."
L["How strong the glow is compared to the art."] = "Насколько сильно свечение по сравнению с изображением."
L["The theme's art (blood, smoke, a glow) that spreads in from the edges as they close in."] = "Изображение темы (кровь, дым, свечение), которое наползает с краев, когда они сжимаются."
L["How many appear per minute at full strength. A big hit adds a few more."] = "Сколько их появляется в минуту на полной силе. Сильный удар добавляет еще несколько."
L["How big they are compared to normal."] = "Насколько они больше или меньше обычного."
L["How strong it is at full, multiplied by the art's opacity."] = "Сила на максимуме, умноженная на непрозрачность изображения."
L["Overall strength, reach and brightness, plus the shadow, the heartbeat and big hits."] = "Общая сила, охват и яркость, а еще тень, сердцебиение и сильные удары."
L["How the screen looks as your mana runs out."] = "Как выглядит экран, когда кончается мана."
L["As your health drops, the edges of the screen close in."] = "Когда здоровье падает, края экрана сжимаются."
L["Shows everywhere, so the other columns don't change anything."] = "Видно везде, так что остальные столбцы ничего не меняют."
L["The edges start closing in when your health drops below this."] = "Края начинают сжиматься, когда здоровье падает ниже этого."
L["The edges are all the way in when your health drops to this. Keep it below Starts."] = "Края сжимаются до конца, когда здоровье падает до этого. Держите ниже «Начала»."
L["How much of your health one hit has to take to count as a big hit."] = "Сколько здоровья должен снять один удар, чтобы считаться сильным."
L["As your mana runs out, the screen drains. Right-click the tab to turn it on."] = "Когда кончается мана, экран блекнет. ПКМ по вкладке — включить."

-- Atmosphere/ManaVision.lua
L["Low mana"] = "Мало маны"
L["The screen starts to drain when your mana drops below this."] = "Экран начинает блекнуть, когда мана падает ниже этого."
L["The screen is fully drained when your mana drops to this. Keep it below Starts."] = "Экран блекнет полностью, когда мана падает до этого. Держите ниже «Начала»."
L["How strong it is out of a fight."] = "Насколько сильно это вне боя."
L["Shows your mana running out on the screen."] = "Показывает на экране, как кончается мана."
L["This character doesn't use mana, so nothing shows."] = "Этот персонаж не использует ману, так что ничего не видно."
L["Drained"] = "Блеклый"
L["Gray-blue: the world's color drains away."] = "Серо-синий: краски мира уходят."
L["Cold"] = "Холод"
L["A cold, deep blue."] = "Холодный глубокий синий."
L["A dim, gray-violet dusk."] = "Тусклые серо-фиолетовые сумерки."
L["How strong the veil and the edges are when your mana is out."] = "Насколько сильны вуаль и края, когда мана кончилась."
L["Dark edges"] = "Темные края"
L["Dark edges close in as your mana runs out."] = "Когда кончается мана, наползают темные края."
L["How far in from the screen's edges they come."] = "Насколько далеко от краев экрана они заходят."
L["Shows your mana running out in the preview and on screen."] = "Показывает, как кончается мана, в предпросмотре и на экране."

-- Atmosphere/TeleportVision.lua
L["Motes in the portal's color drift in from the rim."] = "Пылинки цвета портала плывут внутрь от края."
L["Plays a pretend 8-second cast on screen. Close the settings to see it."] = "Показывает на экране понарошку 8-секундное заклинание. Закройте настройки, чтобы увидеть."

-- Atmosphere/Tint.lua
L["Warm brownish yellow, like an old photo. The world can't be fully desaturated."] = "Теплый коричнево-желтый, как старое фото. Полностью обесцветить мир нельзя."
L["A warm haze over everything."] = "Теплая дымка поверх всего."

-- Camera/CameraManager.lua
L["Right-click to copy it, or to rename, describe, change the icon of or delete one of yours."] = "ПКМ — скопировать, а свою — переименовать, описать, сменить значок или удалить."
L["Makes a copy of this camera's script for you to change, and opens its tab."] = "Делает копию сценария этой камеры, чтобы вы могли его менять, и открывает ее вкладку."

-- Camera/CameraScriptsPage.lua
L["Runs when the camera ends, whatever ends it (its stop rules say what does). Every camera has one and it can't be removed. Pick it and add steps to put them inside."] = "Срабатывает, когда камера заканчивается, что бы ее ни остановило (это решают правила остановки). Есть у каждой камеры, убрать нельзя. Выберите его и добавьте шаги внутрь."
L["Lets scenes play your scripts, and lets our cameras use your changes to their scripts."] = "Сцены могут играть ваши сценарии, а наши камеры — брать ваши изменения своих сценариев."
L["This script as text to share with friends."] = "Этот сценарий в виде текста, чтобы поделиться с друзьями."
L["A haze around the edges of the screen while this camera runs. Set to 0 to turn it off."] = "Дымка по краям экрана, пока работает эта камера. 0 — выключить."
L["A built-in camera you've changed. Reset puts ours back."] = "Встроенная камера, которую вы изменили. «Сброс» вернет нашу."
L["A built-in camera, made from your settings. Any change you make saves it as your own."] = "Встроенная камера по вашим настройкам. Любое изменение сохранит ее как вашу."

-- Camera/CameraTriggerEditor.lua
L["Another trigger for this scene. Any one of its triggers starts it."] = "Еще один триггер для этой сцены. Ее запускает любой из ее триггеров."
L["Turns CineMode on while its camera runs, if Start in CineMode is off."] = "Включает CineMode, пока работает ее камера, если «Запуск в CineMode» выключен."

-- Camera/ShotsPage.lua
L["Copies text you can send a friend, who adds this shot with Import here or on their Scenes page."] = "Копирует текст для друга: он добавит этот кадр через «Импорт» здесь или на своей странице «Сцены»."
L["The camera whose moves this shot uses."] = "Камера, чьи движения использует этот кадр."
L["Clears this shot's numbers so they go back to its camera's own settings."] = "Стирает числа этого кадра, чтобы вернулись настройки его камеры."

-- Camera/ShoulderCalibrate.lua
L["Stops using this measurement and goes back to the built-in size."] = "Перестает использовать этот замер и возвращает встроенный размер."

-- Camera/ShoulderCam.lua
L["Another addon (DynamicCam) is running a shoulder camera, so the Shoulder Cam stays off."] = "Другая модификация (DynamicCam) уже держит камеру через плечо, поэтому «Камера через плечо» остается выключенной."
L["Shoulder Cam uses some experimental Blizzard features, as well as some hacks to fill in the gaps."] = "«Камера через плечо» использует экспериментальные функции Blizzard и пару хитростей, чтобы закрыть пробелы."
L["Which frames slide with you while the camera is over your shoulder."] = "Какие рамки сдвигаются вместе с вами, пока камера смотрит через плечо."
L["Which of Cinematic's cameras keep the Shoulder Cam on while they play."] = "При каких камерах Cinematic «Камера через плечо» остается включенной."
L["Over your shoulder everywhere, so the other columns don't matter."] = "Через плечо везде, так что остальные столбцы не важны."
L["How far from the middle you sit when zoomed out. Set it lower than Spot on screen to keep the camera from catching on walls, which only happens zoomed out."] = "Насколько далеко от центра вы стоите при отдалении. Поставьте меньше, чем «Место на экране», чтобы камера не цеплялась за стены — так бывает только при отдалении."
L["The camera distance where you reach Spot zoomed out. Between 5 yards and this distance, you slide from Spot on screen to Spot zoomed out."] = "Расстояние камеры, на котором вы оказываетесь в «Месте при отдалении». Между 5 м и этим расстоянием вы плавно переходите от «Места на экране» к «Месту при отдалении»."
L["Keep the shoulder when selecting yourself"] = "Не сбрасывать плечо при выборе себя"
L["Selecting yourself clears your target instead, so the camera stays over your shoulder. Heals and buffs still land on you."] = "Выбор себя вместо этого сбрасывает цель, и камера остается за плечом. Исцеления и баффы все равно попадут на вас."
L["Shows our own copy of your target frame, so it matches only the game's look or a Cinematic theme."] = "Показывает нашу копию вашей рамки цели, поэтому она выглядит только как в игре или в теме Cinematic."
L["How long the Shoulder Cam waits to come back over your shoulder after you step outside or get off your mount. Going back in or mounting again during the wait starts it over."] = "Сколько «Камера через плечо» ждет, прежде чем вернуться за плечо, когда вы вышли наружу или слезли с транспорта. Если за это время снова зайти или сесть на транспорт, отсчет начнется заново."
L["Turns to who you talk to everywhere, so the other columns don't matter."] = "Поворачивается к собеседнику везде, так что остальные столбцы не важны."
L["How many seconds the camera takes to move behind you for this camera. Leave it empty to use %s."] = "За сколько секунд камера встает за вашу спину для этой камеры. Оставьте пустым, чтобы взять %s."

-- Camera/SkyrideCam.lua
L["Everywhere you skyride, so the other columns don't matter."] = "Везде, где вы летаете на драконе, так что остальные столбцы не важны."
L["How far past your cruise distance (set in Take off) the camera goes."] = "Насколько дальше крейсерского расстояния (оно задается во «Взлете») отъезжает камера."
L["At 0.5 it's a snap, as fast as the game's zoom can go."] = "При 0.5 — мгновенно, так быстро, как только умеет зум игры."
L["How close the camera comes in. Set to 0 to keep its distance."] = "Насколько близко подъезжает камера. 0 — не менять расстояние."
L["Second Wind brings the camera in a little, then back out."] = "«Второе дыхание» слегка приближает камеру, а потом отдаляет обратно."
L["The fastest the camera can move. Moves that would go faster take longer instead."] = "Самая большая скорость камеры. Более быстрые движения просто займут больше времени."
L["Blends one move into the next. At 0 the camera stops between moves."] = "Плавно сливает одно движение со следующим. При 0 камера останавливается между ними."

-- Camera/TriggersPage.lua
L["For now, its camera follows its own rules for when it plays."] = "Пока что ее камера сама решает, когда играть, по своим правилам."
L["Moves it up, so it wins over the one above."] = "Поднимает его, чтобы он брал верх над тем, что выше."
L["Moves it down, so the one below wins over it."] = "Опускает его, чтобы тот, что ниже, брал над ним верх."
L["Makes a copy of this trigger that you can change on its own."] = "Делает копию этого триггера, которую можно менять отдельно."
L["Puts its Only if, wait, cooldown, chance and priority back to how they came."] = "Возвращает «Только если», ожидание, восстановление, шанс и приоритет к исходным."
L["A wait before it starts, a minimum time, a cooldown and a chance."] = "Ожидание перед запуском, минимальное время, восстановление и шанс."
L["A rule that must be true for it to start. Leave it empty to always start. Click to edit."] = "Условие, которое должно выполняться для запуска. Оставьте пустым, чтобы запускать всегда. Нажмите, чтобы изменить."
L["When on, it waits until its condition is no longer true before it can start again."] = "Если включено, он ждет, пока условие перестанет выполняться, и только потом может запуститься снова."

