-- Profiles/Welcome.lua
L["Playing %s, %d of %d"] = "Показ: %s, %d из %d"
L["Playing %s"] = "Показ: %s"
L["Feature List: Click to preview"] = "Список функций: нажмите, чтобы посмотреть"
L["Watch the tour \194\183 1\194\189 min"] = "Смотреть обзор \194\183 1\194\189 мин"
L["The highlights one after another: %s. Stop any time."] = "Самое интересное, одно за другим: %s. Можно остановить в любой момент."
L["Puts the features you switched here back as the profile you're trying has them."] = "Возвращает функции, которые вы переключили здесь, как в профиле, который вы пробуете."
L["1 switch of yours"] = "Ваших переключений: 1"
L["%d switches of yours"] = "Ваших переключений: %d"
L["Turn %s off"] = "Выключить: %s"
L["Turn %s on"] = "Включить: %s"
L["Takes it out of %s, the profile you're trying."] = "Убирает это из %s — профиля, который вы пробуете."
L["Adds it to %s, the profile you're trying."] = "Добавляет это в %s — профиль, который вы пробуете."
L["It uses one of Blizzard's experimental camera settings: turning it on agrees to that."] = "Это использует экспериментальную настройку камеры Blizzard: включая, вы соглашаетесь с этим."
L["You turned it on."] = "Вы это включили."
L["You turned it off."] = "Вы это выключили."
L["See all"] = "Все"
L["Everything Cinematic can show you, by where you'll find it in the settings. Click any to see it."] = "Все, что Cinematic может показать, по тому, где это лежит в настройках. Нажмите на любое, чтобы посмотреть."
L["Find a feature: fishing, duel, camera..."] = "Найти функцию: рыбалка, дуэль, камера..."
L["You're in a fight. The demos come back when it ends."] = "Вы в бою. Показ продолжится, когда бой закончится."
L["Also in Cinematic:"] = "А еще в Cinematic:"
L["Nothing to play: click to open its settings. Closing them brings you back here."] = "Показывать нечего: нажмите, чтобы открыть его настройки. Когда закроете их, вернетесь сюда."
L["Nothing to play for that: it's a setting, below."] = "Тут нечего показывать: это настройка, она ниже."
L["Nothing called \"%s\" plays here."] = "Здесь нет показа \"%s\"."
L["Plays each in turn, a few seconds each. Stop any time."] = "Показывает по очереди, по несколько секунд. Можно остановить в любой момент."
L["See all %d"] = "Все (%d)"
L["%d more"] = "Еще %d"
L["In a fight: demos wait till it ends."] = "В бою: показ подождет до конца боя."
L["Stop the tour"] = "Остановить обзор"
L["Play these"] = "Показать эти"
L["Play all"] = "Показать все"
L["Play all in %s"] = "Показать все в %s"
L["< Back to the welcome window"] = "< Назад к окну приветствия"
L["turned off. /cine welcome brings this window back to pick a profile."] = "выключено. /cine welcome вернет это окно, чтобы выбрать профиль."

