-- Style/BubbleStyle.lua
L["Just the words, with no bubble. An outline makes them easier to read."] = "Только слова, без облачка. С обводкой их легче читать."
L["How big speech from behind you is compared to a bubble overhead. Smaller makes it seem farther away."] = "Насколько велика речь из-за спины по сравнению с облачком над головой. Меньше — кажется дальше."
L["How solid speech from behind you looks. Fainter makes it seem muffled and out of view."] = "Насколько плотной выглядит речь из-за спины. Бледнее — кажется приглушенной и вне поля зрения."

-- Style/CdmStyle.lua
L["After a few hits"] = "После пары ударов"
L["Draining"] = "Убывает"
L["Just cast"] = "Только что"
L["Halfway"] = "Наполовину"
L["Cooldown Manager Style"] = "Стиль менеджера восстановления"
L["How the drain ring on your tracked buffs looks. Pick which buffs get one on the Cooldown Manager page, under Look."] = "Как выглядит убывающее кольцо на отслеживаемых баффах. Какие баффы его получат, выберите на странице «Менеджер восстановления», в разделе «Вид»."
L["Turns this page's ring look on or off. Off: the ring's own look."] = "Включает или выключает вид кольца с этой страницы. «Выкл.»: собственный вид кольца."
L["How the drain ring on your tracked buffs looks."] = "Как выглядит убывающее кольцо на отслеживаемых баффах."
L["The Cooldown Manager icons' shape."] = "Форма значков менеджера восстановления."
L["Cooldown + DoT"] = "Восстановление + DoT"
L["How a spell's cooldown shows over its DoT, on rows whose Shows is Both."] = "Как восстановление заклинания показывается поверх его DoT в строках, где «Показ» стоит на «Оба»."
L["The icons take Action Bar Style's shape."] = "Значки берут форму из «Стиля панелей команд»."
L["Square icons, whatever the action buttons are."] = "Квадратные значки, какими бы ни были кнопки команд."
L["Round icons, whatever the action buttons are."] = "Круглые значки, какими бы ни были кнопки команд."
L["Pips"] = "Деления"
L["Eight chunky segments round the icon."] = "Восемь толстых делений вокруг значка."
L["One thin ring round the icon."] = "Одно тонкое кольцо вокруг значка."
L["Liquid"] = "Жидкость"
L["The icon empties from the top down."] = "Значок пустеет сверху вниз."
L["Bar under"] = "Полоса снизу"
L["A thin bar under the icon."] = "Тонкая полоса под значком."
L["How big the ring is next to the icon."] = "Насколько велико кольцо по сравнению со значком."
L["Empty part"] = "Пустая часть"
L["How dark the spent part shows. 0: hidden."] = "Насколько темной видна прошедшая часть. 0: скрыта."
L["The ring in your class's color."] = "Кольцо цвета вашего класса."
L["From the full end's color to the empty end's: what's left turns toward the empty color as it drains."] = "От цвета полного конца к цвету пустого: остаток по мере убывания уходит в цвет пустого."
L["The color you pick below."] = "Цвет, который вы выберете ниже."
L["A plain white ring."] = "Простое белое кольцо."
L["Click to choose the ring's color."] = "Нажмите, чтобы выбрать цвет кольца."
L["Full end"] = "Полный конец"
L["The gradient's color where the shield is full."] = "Цвет градиента там, где щит полон."
L["Empty end"] = "Пустой конец"
L["The gradient's color where the shield runs out."] = "Цвет градиента там, где щит кончается."
L["Left / right"] = "Влево / вправо"
L["Moves the amount left or right from the icon's middle."] = "Сдвигает число влево или вправо от центра значка."
L["Down / up"] = "Вниз / вверх"
L["Moves the amount down or up from the icon's middle."] = "Сдвигает число вниз или вверх от центра значка."
L["How big the amount's text is."] = "Размер текста числа."
L["Which buffs get a ring, and the game's timer: the Cooldown Manager page, under Look."] = "Какие баффы получают кольцо и таймер игры — на странице «Менеджер восстановления», в разделе «Вид»."
L["Pips in a ring round the icon."] = "Деления по кругу вокруг значка."
L["Edge pips"] = "Деления по краю"
L["Square pips along the icon's edge."] = "Квадратные деления по краю значка."
L["Row pips"] = "Деления в ряд"
L["A row of square pips under the icon."] = "Ряд квадратных делений под значком."
L["Corner number"] = "Число в углу"
L["The cooldown's seconds in the icon's corner."] = "Секунды восстановления в углу значка."
L["Pips:"] = "Деления:"
L["Four pips: a big step each."] = "Четыре деления: каждое — большой шаг."
L["Eight pips."] = "Восемь делений."
L["Twelve pips: small steps."] = "Двенадцать делений: мелкие шаги."
L["Plain white."] = "Просто белый."
L["Click to choose the cooldown's color."] = "Нажмите, чтобы выбрать цвет восстановления."
L["Which spells show both: the Cooldown Manager page, Look, Shows."] = "Какие заклинания показывают оба — на странице «Менеджер восстановления», «Вид», «Показ»."

-- Style/CombatTextPage.lua
L["You may see other people's damage as your own."] = "Чужой урон может показываться как ваш."
L["Each text starts out looking like the one it's under. Changing one only changes that one."] = "Каждый текст поначалу выглядит как тот, под которым он стоит. Если изменить один, меняется только он."
L["Spells"] = "Заклинания"
L["A look of their own for any of your spells."] = "Свой вид для любого вашего заклинания."
L["Ours look the way the Look tab sets them. The game's look as they always do."] = "Наши выглядят так, как задано на вкладке «Вид». Игровые — как обычно."
L["The game's own numbers, the way it normally draws them."] = "Цифры самой игры, как она обычно их рисует."
L["Set XP and other floating text to The game's first. While it's on None, the game draws none of its numbers."] = "Сначала поставьте «Опыт и другой всплывающий текст» на «Игровой». Пока там «Нет», игра не рисует ни одной своей цифры."
L["Ours when you're solo. In a group or raid, the game's own, which show every pet hit."] = "«Наши», когда вы одни. В группе или рейде — игровые, они показывают каждый удар питомца."
L["In a group, ours only show your pet's spells, since its swings look the same as everyone else's. The game's shows every pet hit in its own look."] = "В группе наши показывают только заклинания питомца: его обычные удары не отличить от чужих. «Игровой» показывает каждый удар питомца в своем виде."
L["Hides all the game's floating text, damage numbers included. Log out and back in to apply."] = "Скрывает весь всплывающий текст игры, и цифры урона тоже. Чтобы применить, перезайдите в игру."
L["Log out and back in to apply. With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "Чтобы применить, перезайдите в игру. Пока он скрыт, игра не рисует свои цифры, поэтому «Игровой» в строках выше недоступен."
L["Log out and back in to apply: until then the game's floating text stays hidden."] = "Чтобы применить, перезайдите в игру: до тех пор всплывающий текст игры скрыт."
L["None hides all of the game's floating text, damage numbers included. It takes a log out and back in."] = "«Нет» скрывает весь всплывающий текст игры, и цифры урона тоже. Нужно перезайти в игру."
L["Each row sets many texts at once. You can change any of them afterward in the table below."] = "Каждая строка настраивает сразу много текстов. Любой из них потом можно поменять в таблице ниже."
L["Shows only your crits and misses, with plain hits and heals turned off."] = "Показывает только ваши криты и промахи, а обычные удары и исцеления выключены."
L["Plain hits and heals are off and crits and misses are on. Switch any of them back in the table."] = "Обычные удары и исцеления выключены, криты и промахи включены. Любое можно вернуть в таблице."
L["Turns off your auto attacks, along with their crits and misses."] = "Выключает ваши автоатаки вместе с их критами и промахами."
L["Crits and your casts show in the middle, and the rest move aside."] = "Криты и ваши заклинания в центре, а остальное в стороне."
L["Your pet's hits show smaller than yours."] = "Удары питомца мельче ваших."
L["Your pet's hits show as big as yours."] = "Удары питомца такие же крупные, как ваши."
L["Every number is three quarters of the game's size."] = "Каждая цифра в три четверти игрового размера."
L["Swings are smaller, and spells and heals get bigger the longer their cast."] = "Обычные удары мельче, а заклинания и исцеления тем крупнее, чем дольше они произносятся."
L["Every number stays three quarters as long as the game's."] = "Каждая цифра держится три четверти игрового времени."
L["Swings stay up for less time, and spells and heals stay longer the longer their cast."] = "Обычные удары держатся меньше, а заклинания и исцеления тем дольше, чем дольше они произносятся."
L["Puts everything on this tab back to its defaults."] = "Возвращает все на этой вкладке к значениям по умолчанию."
L["How big it is compared to the game's."] = "Размер по сравнению с игровым."
L["How big its crits are compared to its hits."] = "Насколько криты крупнее обычных ударов."
L["Adds (Glancing), (Blocked) or (Resisted) after the number. In a fight, the amount is hidden."] = "Добавляет после числа (Вскользь), (Блок) или (Сопротивление). В бою число скрыто."
L["How far it moves compared to the game's."] = "Насколько далеко он летит по сравнению с игровым."
L["How long it stays compared to the game's."] = "Сколько он держится по сравнению с игровым."
L["How far into its time on screen it starts to fade."] = "В какой момент своего показа он начинает гаснуть."
L["Grows big for a moment, then settles, like the game's crits."] = "На миг увеличивается, а потом успокаивается, как игровые криты."
L["Shows or hides it. Turning it off hides the texts under it too, except crits, which have their own."] = "Показывает или скрывает. Если выключить, скроются и тексты под ним, кроме критов — у них своя настройка."
L["This text's own look, on top of the one above it."] = "Собственный вид этого текста поверх того, что выше."
L["Your own word in place of the game's (%s). Leave it empty to use the game's."] = "Ваше слово вместо игрового (%s). Оставьте пустым, чтобы было игровое."

-- Style/CombatTextSpells.lua
L["Spells and abilities"] = "Заклинания и способности"
L["Same look"] = "Тот же вид"
L["Your spells"] = "Ваши заклинания"
L["Each spell starts out looking like its school on the Look tab. Change only what you want."] = "Каждое заклинание поначалу выглядит как его школа на вкладке «Вид». Меняйте только то, что хотите."
L["+ Add a spell"] = "+ Добавить заклинание"
L["Add a spell"] = "Добавить заклинание"
L["Lists the spells you've hit with, then the rest of your spellbook."] = "Показывает заклинания, которыми вы уже били, а потом остальную книгу заклинаний."
L["Find a spell"] = "Найти заклинание"
L["Shows only the spells whose name has this in it. Press Enter to add a spell by its name."] = "Показывает только заклинания, в названии которых это есть. Enter — добавить заклинание по названию."
L["Every spell on the list."] = "Все заклинания в списке."
L["Changed"] = "Измененные"
L["Only spells with a look of their own."] = "Только заклинания со своим видом."
L["Puts every spell's look back to its school's. The list stays."] = "Возвращает всем заклинаниям вид их школы. Список остается."
L["Crits"] = "Криты"
L["Ticks"] = "Тики"
L["No spells yet. Click + Add a spell to give one a look of its own."] = "Заклинаний пока нет. Нажмите «+ Добавить заклинание», чтобы дать какому-нибудь свой вид."
L["As its hits"] = "Как удары"
L["This spell"] = "Это заклинание"
L["Clear this spell"] = "Сбросить заклинание"
L["Its crits"] = "Его криты"
L["Its crits' color"] = "Цвет его критов"
L["Its ticks"] = "Его тики"
L["Its ticks look like its hits."] = "Его тики выглядят как его удары."
L["Its ticks are three quarters of its hits' size."] = "Его тики в три четверти размера ударов."
L["Shows this spell's numbers or not."] = "Показывать ли цифры этого заклинания."
L["Its color. Right-click: its school's again."] = "Его цвет. ПКМ — снова цвет школы."
L["How big its numbers are. Right-click: its school's again."] = "Размер его цифр. ПКМ — снова как у школы."
L["Its crits' color: its color unless set. Right-click: its color again."] = "Цвет его критов: если не задан, то его цвет. ПКМ — снова его цвет."
L["Its ticks (a DoT's, a channel's): the same as its hits, or smaller."] = "Его тики (от DoT или поддерживаемого заклинания): как удары или мельче."
L["More..."] = "Еще..."
L["Every part of its look: its font, place and motion too."] = "Все части его вида: шрифт, место и движение тоже."
L["Takes it off the list. Its numbers look like its school's again."] = "Убирает его из списка. Его цифры снова выглядят как у школы."
L["Same"] = "То же"
L["Off on the Look tab"] = "Выкл. на вкладке «Вид»"
L["No spells match."] = "Подходящих заклинаний нет."
L["%d spells, %d with a look of their own"] = "Заклинаний: %d, со своим видом: %d"
L["Search your spells"] = "Поиск по заклинаниям"
L["Your spells that hit (this character)"] = "Ваши заклинания, которыми вы били (этот персонаж)"
L["Other spells in your spellbook"] = "Другие заклинания из книги"
L["Not seen yet"] = "Еще не было"
L["In the list"] = "В списке"
L["%d hits"] = "Ударов: %d"
L["No spells found."] = "Заклинания не найдены."

-- Style/InterfaceRecolor.lua
L["Uses General's bar texture for progress bars, and the theme's color for the fold buttons."] = "Берет текстуру полос из «Общих» для полос прогресса и цвет темы для кнопок сворачивания."
L["Uses General's bar texture for its bars, each in its own color."] = "Берет текстуру полос из «Общих» для своих полос, каждую своего цвета."
L["Uses General's text font for its names and numbers."] = "Берет шрифт текста из «Общих» для своих имен и цифр."
L["Uses General's bar texture for the bars' fill, with each weapon in its own color."] = "Берет текстуру полос из «Общих» для заливки полос, каждое оружие своим цветом."
L["Uses General's text font for the bars' text."] = "Берет шрифт текста из «Общих» для текста на полосах."
L["Uses General's text font for their numbers."] = "Берет шрифт текста из «Общих» для их цифр."

-- Style/LetterboxStyle.lua
L["Preview:"] = "Предпросмотр:"
L["The weather the Preview shows."] = "Погода, которую показывает предпросмотр."
L["Shows this weather's tint at its heaviest for a few seconds (at 50% while Strength is Off)."] = "Показывает оттенок этой погоды на максимуме на несколько секунд (на 50%, пока «Сила» стоит на «Выкл.»)."
L["On the screen"] = "На экране"
L["Shows it for a few seconds, in CineMode or not (at 50% while it's Off)."] = "Показывает на несколько секунд, в CineMode или без него (на 50%, пока выключено)."
L["Heavier weather"] = "Погода сильнее"
L["Medium"] = "Средняя"
L["Heavy"] = "Сильная"
L["Makes the game's own rain and snow thicker while its row is on, and puts yours back after."] = "Делает игровой дождь и снег гуще, пока включена их строка, а потом возвращает ваши настройки."
L["Pulls the view distance in as a downpour would, for a few seconds."] = "Сокращает дальность обзора, как в ливень, на несколько секунд."
L["The world"] = "Мир"
L["Draw the world between the bars"] = "Мир между полосами целиком"
L["Shows the whole view between the bars instead of hiding its top and bottom (it changes only out of fights)."] = "Показывает весь обзор между полосами, а не прячет его верх и низ (меняется только вне боя)."
L["Shows the whole time in CineMode, including fights and the Calm Timer after them."] = "Видно все время в CineMode, в бою и в таймер затишья после него тоже."
L["When on, the bars look the way this page sets them. When off, they're Cinematic's plain black bars."] = "Если включено, полосы выглядят так, как задано на этой странице. Если выключено — простые черные полосы Cinematic."
L["Takes the bars out and brings them back in, like at the start and end of a fight."] = "Убирает полосы и возвращает их, как в начале и конце боя."
L["Shapes the space between the bars like a movie screen, on any monitor."] = "Делает место между полосами похожим на киноэкран, на любом мониторе."
L["How tall the top bar is, as a share of the screen's height."] = "Высота верхней полосы как доля высоты экрана."
L["Click to link or unlink the two bars. Linked, they're the same height."] = "Нажмите, чтобы связать или разделить полосы. Связанные — одной высоты."
L["How tall the bottom bar is, as a share of the screen's height."] = "Высота нижней полосы как доля высоты экрана."
L["How long the bars take to come in or go. Set to 0 to match the UI's fade."] = "Сколько полосы появляются или уходят. 0 — вместе с исчезновением интерфейса."
L["How the weather tints the scene: a color for each weather, and how fast it comes in and goes."] = "Как погода окрашивает сцену: цвет для каждой погоды и как быстро она приходит и уходит."
L["When on, the weather uses the colors and time set here. When off, Cinematic's own."] = "Если включено, погода берет цвета и время отсюда. Если выключено — стандартные Cinematic."
L["Pick this weather's tint. White is no change; darker colors darken the scene more."] = "Выберите оттенок этой погоды. Белый ничего не меняет; чем темнее цвет, тем темнее сцена."
L["How long the weather's tint takes to come in as it starts, or to go as it clears or you step inside."] = "Сколько оттенок погоды проявляется, когда она начинается, или уходит, когда проясняется или вы заходите в помещение."

-- Style/MinimapStyle.lua
L["Minimap Style"] = "Стиль миникарты"
L["How the minimap looks: its shape, border and ring."] = "Как выглядит миникарта: форма, рамка и кольцо."
L["Turns this page's minimap look on or off."] = "Включает или выключает вид миникарты с этой страницы."
L["Size and shape"] = "Размер и форма"
L["How big the minimap is."] = "Размер миникарты."
L["Makes the minimap square."] = "Делает миникарту квадратной."
L["Border size"] = "Толщина рамки"
L["How thick the border round the square minimap is. 0: no border."] = "Толщина рамки вокруг квадратной миникарты. 0: без рамки."
L["Border color:"] = "Цвет рамки:"
L["Theme uses your theme's ring color, or black when it has none."] = "«Тема» берет цвет кольца вашей темы, а если его нет — черный."
L["Zone name and clock inside"] = "Зона и часы внутри"
L["Puts the zone name at the top of the square minimap and the clock in its corner."] = "Ставит название зоны вверху квадратной миникарты, а часы — в угол."
L["Zoom buttons"] = "Кнопки масштаба"
L["Hides the minimap's zoom buttons."] = "Скрывает кнопки масштаба миникарты."
L["Hides the zone name bar over the minimap."] = "Скрывает полосу с названием зоны над миникартой."
L["Hides the day and night dial on the minimap's edge."] = "Скрывает циферблат дня и ночи на краю миникарты."
L["Ring and buttons"] = "Кольцо и кнопки"
L["Colors the rings around minimap buttons in your theme's ring color, or the border color when it has none."] = "Красит кольца вокруг кнопок миникарты в цвет кольца темы, а если его нет — в цвет рамки."
L["A little shading just inside the ring, so the map looks set into it."] = "Легкая тень по внутреннему краю кольца, будто карта вставлена в него."
L["Zone bar in the theme's look"] = "Полоса зоны в виде темы"
L["Shade and the zone bar's look come with themes that have a ring color."] = "Тень и вид полосы зоны есть у тем, у которых есть цвет кольца."

-- Style/PersonalStyle.lua
L["When on, the bars look the way this page sets them. When off, they use the game's own look."] = "Если включено, полосы выглядят так, как задано на этой странице. Если выключено — как в игре."
L["It fades to a darker shade of its own color."] = "Она гаснет в более темный оттенок своего цвета."
L["Its width in screen pixels, so the same number gives two bars the same width."] = "Ширина в пикселях экрана: одно и то же число дает двум полосам одну ширину."
L["The health bar's width, growing out from its middle."] = "Ширина полосы здоровья, растет от центра."
L["The power bar's width, growing out from its middle."] = "Ширина полосы ресурса, растет от центра."
L["The mana bar's width as a percent of the game's power bar, growing out from its middle."] = "Ширина полосы маны в процентах от игровой полосы ресурса, растет от центра."
L["The health bar's height compared to the game's."] = "Высота полосы здоровья по сравнению с игровой."
L["The power bar's height compared to the game's."] = "Высота полосы ресурса по сравнению с игровой."
L["How big your class resource is compared to the game's size."] = "Размер ресурса вашего класса по сравнению с игровым."
L["The mana bar's height compared to the power bar's."] = "Высота полосы маны по сравнению с полосой ресурса."
L["The bars' border: the game's or one of ours. Custom sets its thickness and color below."] = "Рамка полос: игровая или одна из наших. «Свой» — толщина и цвет задаются ниже."

-- Style/PlateCastStyle.lua
L["When on, the cast bars look the way this page sets them. When off, they use the game's own look."] = "Если включено, полосы заклинаний выглядят так, как задано на этой странице. Если выключено — как в игре."
L["Makes it part of the unit frame, with its fill, border and font, right under its bars."] = "Делает ее частью рамки юнита, с ее заливкой, рамкой и шрифтом, прямо под полосами."
L["Pick the color of an interrupted cast. The game doesn't report this in every fight."] = "Выберите цвет прерванного заклинания. Игра сообщает о прерывании не в каждом бою."
L["How dark it is behind the fill. This only works with a fill of your own; the game's keeps its own."] = "Насколько темно за заливкой. Работает только со своей заливкой; у игровой — свой фон."
L["Its width compared to the game's, growing out from its middle. Nameplates only."] = "Ширина по сравнению с игровой, растет от центра. Только для индикаторов."
L["The cast bar's height compared to the game's."] = "Высота полосы заклинания по сравнению с игровой."
L["The icon's size compared to the game's."] = "Размер значка по сравнению с игровым."
L["A dark shadow behind the letters, down and to the right."] = "Темная тень за буквами, вниз и вправо."
L["The look every cast bar uses while its row is set to Default."] = "Вид всех полос заклинаний, у которых строка стоит на «По умолчанию»."
L["Default's (Cast Bars)"] = "Как «По умолчанию» (полосы заклинаний)"

-- Style/QuestItemStyle.lua
L["When on, the button looks the way this page sets it. When off, it looks like the game's extra ability button."] = "Если включено, кнопка выглядит так, как задано на этой странице. Если выключено — как игровая кнопка особой способности."
L["Icons have their own dark border. Zooming in a little cuts it off."] = "У значков есть своя темная кайма. Небольшое увеличение ее обрезает."
L["A black border around its numbers."] = "Черная обводка вокруг цифр."

-- Style/QuestTalkStyle.lua
L["When on, the dialogue looks the way this page sets it. When off, it uses the game's parchment."] = "Если включено, диалог выглядит так, как задано на этой странице. Если выключено — игровой пергамент."
L["The size of the bubble and the reply list. Their text grows with them."] = "Размер облачка и списка ответов. Текст растет вместе с ними."
L["A black border around the letters, for light text with no panel behind it."] = "Черная обводка вокруг букв, для светлого текста без подложки."
L["The bubble's text in a color of your own. The quest card keeps its own color."] = "Текст облачка своим цветом. Карточка задания остается своего цвета."

-- Style/RaidStyle.lua
L["When on, the raid frames look the way this page sets them. When off, they use the game's own look."] = "Если включено, рамки рейда выглядят так, как задано на этой странице. Если выключено — как в игре."
L["Uses the color below at full health, shifting to the At half and Empty colors as health drops."] = "При полном здоровье — цвет ниже, а по мере потери здоровья он переходит в цвета «На половине» и «Пусто»."
L["Tints the game's background a color of your own, picked below."] = "Красит фон игры в ваш цвет, выбранный ниже."
L["The name's size compared to the game's."] = "Размер имени по сравнению с игровым."
L["The look every group uses while its row is set to Same as the Default row."] = "Вид всех групп, у которых строка стоит на «Как строка «По умолчанию»»."

-- Style/RollStyle.lua
L["When on, the window looks the way this page sets it. When off, it uses Roll Vision's usual look."] = "Если включено, окно выглядит так, как задано на этой странице. Если выключено — обычный вид Roll Vision."
L["A dark panel with a thin line around it, in the item's quality color."] = "Темная панель с тонкой линией вокруг цвета качества предмета."

