L["Plays samples of your combat text, over and over."] = "Снова и снова показывает примеры вашего текста боя."
L["Over shoulder"] = "Через плечо"
L["Shows you as the Shoulder Cam puts you, or right behind you."] = "Показывает вас так, как ставит камера через плечо, или прямо со спины."
L["Behind you"] = "Со спины"
