L["Sits beside you while the camera is over your shoulder."] = "Стоит рядом с вами, пока камера смотрит через плечо."
L["Moves it up or down from your spot."] = "Сдвигает вверх или вниз от вашего места."
L["Moves it left or right from your spot."] = "Сдвигает влево или вправо от вашего места."
L["How long each text stays."] = "Сколько держится каждый текст."
L["Curves out to the side."] = "Уходит дугой в сторону."
L["Pop"] = "Всплеск"
L["Crits start big and settle."] = "Криты появляются крупными и уменьшаются."
