-- Style/StyleOverrides.lua
L["Hide or show parts of unit frames and nameplates, no matter what their Show rows say."] = "Скрывайте или показывайте части рамок юнитов и индикаторов, что бы ни говорили их строки «Показывать»."

-- Style/StylePages.lua
L["Opens its settings: when it shows, and what it does."] = "Открывает его настройки: когда он виден и что делает."
L["Puts this setting back to its default."] = "Возвращает эту настройку к значению по умолчанию."
L["Hold it down to see the sample without this row's own changes, then let go to see them again."] = "Удерживайте, чтобы увидеть пример без изменений этой строки, и отпустите, чтобы снова их увидеть."
L["Puts every setting in this panel back to its default."] = "Возвращает все настройки на этой панели к значениям по умолчанию."
L["Puts every setting in this panel back to inherited, so the row takes its look from above again."] = "Возвращает все настройки на этой панели к унаследованным, чтобы строка снова брала вид сверху."

-- Style/StyleThemes.lua
L["Put %s back to how it came? Your changes will be lost."] = "Вернуть %s к исходному виду? Ваши изменения пропадут."
L["A line of text to send a friend, who adds it with Import under Yours."] = "Строка текста для друга: он добавит ее через «Импорт» в разделе «Ваши»."
L["The built-in theme it's based on, which gives it its art, shapes and fonts under your colors and changes."] = "Встроенная тема, на которой она основана: от нее изображения, формы и шрифты, а сверху ваши цвета и изменения."
L["Right-click to put it back to its starting theme's."] = "ПКМ — вернуть как в исходной теме."

-- Style/TintStyle.lua
L["Applies to every look. A place can have its own on Zone mood."] = "Действует для всех видов. У места может быть свой в «Настроении зоны»."
L["Your own tint. Once it's picked, click it again to change it."] = "Ваш собственный оттенок. Когда он выбран, нажмите еще раз, чтобы изменить."

-- Style/TooltipStyle.lua
L["When on, tooltips look the way this page sets them. When off, they use the game's own look."] = "Если включено, подсказки выглядят так, как задано на этой странице. Если выключено — как в игре."
L["Green, or the color the game gives that unit."] = "Зеленый или цвет, который игра дает этому юниту."

-- Style/UnitStyle.lua
L["Turn this on to style the unit frames as this page says, or off to keep the game's own look."] = "Включите, чтобы оформить рамки юнитов как на этой странице, или выключите, чтобы оставить вид игры."
L["Whether this frame uses the Default row's look or its own."] = "Берет ли эта рамка вид строки «По умолчанию» или свой."

-- Style/VisionsStyle.lua
L["Makes every Vision's text bigger or smaller, on top of each one's own size on its page (cards too)."] = "Делает текст всех Visions крупнее или мельче, поверх размера на странице каждой (и карточки тоже)."

