L["Set by"] = "Задается"
L["How the bars' height is set."] = "Как задается высота полос."
L["Same top and bottom"] = "Одинаковые сверху и снизу"
L["Both bars the same height, the top bar's."] = "Обе полосы одной высоты — как верхняя."
