L["Next to the game's plate."] = "По сравнению с игровым индикатором."
L["The health bar's width: every plate's on Default, times that on a row's plates."] = "Ширина полосы здоровья: для всех индикаторов — в «По умолчанию», а на индикаторах строки — с этим множителем."
L["The health bar's height: every plate's on Default, times that on a row's plates."] = "Высота полосы здоровья: для всех индикаторов — в «По умолчанию», а на индикаторах строки — с этим множителем."
L["Each kind of unit's plate color, under every Smart row. Class is for players only."] = "Цвет индикатора для каждого типа юнитов, под всеми строками «Умного». «Класс» — только для игроков."
L["How each kind's bar color runs along it, left to right."] = "Как цвет полосы каждого типа идет по ней слева направо."
