L["Default's colors"] = "Цвета «По умолчанию»"
L["By kind of unit, from Default's Colors"] = "По типу юнита, из «Цветов» в «По умолчанию»"
L["The same color as this row's mark"] = "Тот же цвет, что у метки строки"
