L["Border in it"] = "Рамка этим цветом"
L["The border the game puts round your target's health bar, in the row's plate color."] = "Рамка, которую игра рисует вокруг полосы здоровья цели, цветом индикатора строки."
L["How this row's bar color runs along it, left to right."] = "Как цвет полосы этой строки идет по ней слева направо."
L["The name's size, next to its usual size."] = "Размер имени по сравнению с обычным."
L["A dark line around the name's letters."] = "Темная линия вокруг букв имени."
