L["What this part hangs on. Moving that part moves this one with it."] = "К чему крепится эта часть. Если сдвинуть ту часть, эта сдвинется вместе с ней."
L["Which side of that part it sits on."] = "С какой стороны той части она стоит."
L["Moves it left or right, in the plate's own units. The arrow keys over the plate do the same."] = "Сдвигает влево или вправо, в единицах индикатора. Стрелки на клавиатуре над индикатором делают то же."
