L["Whether this part counts when Center is Balanced: always, only while it's up, or never."] = "Учитывается ли эта часть, когда «Центр» стоит на «Сбалансированный»: всегда, только когда видна, или никогда."
L["Mirrored"] = "Зеркально"
L["On the other side of the bar, as far out. Off puts it back where it was."] = "С другой стороны полосы, на том же расстоянии. «Выкл.» возвращает обратно."
L["Your game's nameplate settings hide %s, so it won't show on your plates."] = "Настройки индикаторов в игре скрывают %s, поэтому на ваших индикаторах этого не будет."
L["Smart marks"] = "Метки «Умного»"
