L["Down/up without a plate"] = "Вниз/вверх без индикатора"
L["Layout for"] = "Макет для"
L["Every part where the game puts it."] = "Каждая часть там, где ее ставит игра."
L["The game's places, the plate centered on its unit."] = "Места как в игре, индикатор по центру юнита."
L["The level box and marker inside the bar, balanced."] = "Рамка уровня и метка внутри полосы, сбалансированно."
L["Name in the bar"] = "Имя в полосе"
