-- Style/Studio/Frames/Names.lua
L["A dark shadow behind the letters so they stand out."] = "Темная тень за буквами, чтобы они выделялись."
L["Shadow strength"] = "Сила тени"
L["%s, picked here, so it stays when the main theme changes."] = "%s, выбрано здесь, поэтому останется при смене основной темы."
L["Players in their class color, everyone else by their reaction to you."] = "Игроки цветом класса, остальные — по отношению к вам."
L["The camera is %d yards from you: every name is sized as if its unit were about %d yards from it."] = "Камера в %d м от вас: каждое имя такого размера, будто его юнит примерно в %d м от нее."
L["You're not in CineMode, so names over heads are the game's own; the preview shows this page's look."] = "Вы не в CineMode, поэтому имена над головами игровые; предпросмотр показывает вид этой страницы."
L["Names here are the game's own (in dungeons and raids, or with the Nameplates page off), which this page can't change."] = "Здесь имена игровые (в подземельях и рейдах или при выключенной странице «Индикаторы»), и эта страница не может их изменить."
L["A whole look for every name in one pick."] = "Готовый вид для всех имен одним выбором."
L["How big the names are compared to the plates' own."] = "Размер имен по сравнению с собственными именами индикаторов."
L["Blue, like the game's names over their heads."] = "Синий, как у игровых имен над головами."
L["The glow's color."] = "Цвет свечения."
L["The band's color."] = "Цвет ленты."
L["The band's border color."] = "Цвет рамки ленты."
L["Second line"] = "Вторая строка"
L["Its own font, outline and shadow, starting from the name's."] = "Свой шрифт, обводка и тень, поначалу как у имени."
L["The guild or title under the name, sized compared to the name."] = "Гильдия или звание под именем, размер относительно имени."
L["Puts < > around a title shown without its NPC's name."] = "Ставит < > вокруг звания, показанного без имени НИП."
L["Puts < > around every title, including under the name."] = "Ставит < > вокруг каждого звания, и под именем тоже."
L["Titles are set on Default and the Service NPCs rows."] = "Звания задаются в строках «По умолчанию» и «Служебные НИП»."
L["Distance"] = "Расстояние"
L["Near"] = "Близко"
L["Names close by, the camera zoomed in."] = "Имена вблизи, камера приближена."
L["Far"] = "Далеко"
L["Names more than 28 yards away, the camera zoomed out."] = "Имена дальше 28 м, камера отдалена."
L["Shows the names near or far in the preview."] = "Показывает в предпросмотре имена вблизи или вдали."
L["Retail's plates size names by distance themselves."] = "В Retail индикаторы сами меняют размер имен по расстоянию."
L["Size by"] = "Размер по"
L["Names grow as you zoom in and shrink as you zoom out."] = "Имена растут при приближении камеры и уменьшаются при отдалении."
