L["Distance settings are the same for every name: they're on Default."] = "Настройки расстояния одинаковы для всех имен: они в «По умолчанию»."
L["A drop shadow behind the letters, with a thick outline."] = "Тень за буквами и толстая обводка."
L["Speech from behind you shows once these are on: %s."] = "Речь из-за спины появится, когда это будет включено: %s."
