-- Style/Studio/Frames/Visions.lua
L["Its font, outline, shadow, texture and border as this page says."] = "Шрифт, обводка, тень, текстура и рамка — как на этой странице."
L["It keeps its own; picking this again puts back what it had."] = "Оставляет свое; если выбрать снова, вернется то, что было."
L["Whether it follows this page or keeps its own look."] = "Следует ли он этой странице или оставляет свой вид."
L["Edit %s"] = "Изменить: %s"
L["Opens its look."] = "Открывает его вид."
L["A dark line around the letters, on every Vision that follows this page."] = "Темная линия вокруг букв у всех Visions, которые следуют этой странице."
L["All Visions"] = "Все Visions"
L["Makes every Vision's text bigger or smaller, on top of each one's own size."] = "Делает текст всех Visions крупнее или мельче, поверх размера каждой."
L["A dark shadow behind the letters, on every Vision that follows this page."] = "Темная тень за буквами у всех Visions, которые следуют этой странице."
L["Follows"] = "Следует"
L["Amber while you're behind, teal once you lead."] = "Янтарный, пока вы отстаете, бирюзовый, когда вы впереди."
L["Your two colors: this one while you're behind, the next once you lead."] = "Ваши два цвета: этот, пока вы отстаете, следующий — когда вы впереди."
L["The bar's color while you're behind, and once you lead."] = "Цвет полосы, пока вы отстаете и когда вы впереди."
L["Once you lead"] = "Когда вы впереди"
L["The bar's color once you lead; picking one switches it to Custom."] = "Цвет полосы, когда вы впереди; если выбрать цвет, включится «Свой»."
L["The bars glide to each new value instead of jumping."] = "Полосы плавно доходят до нового значения, а не прыгают."
L["Adds a bright spark at the edge of the filled part."] = "Добавляет яркую искру на краю заполненной части."
L["The line around the bars."] = "Линия вокруг полос."
L["The words' size compared to their normal size."] = "Размер слов по сравнению с обычным."
L["How dark the panel behind it is. Set to 0 for no panel."] = "Насколько темная панель позади. 0 — без панели."
L["Sits"] = "Где стоит"
L["Off, everything in this part is off."] = "Если выключено, все в этой части выключено."
L["The theme's sparks and the haze drifting over the edges."] = "Искры темы и дымка, плывущая по краям."
L["Spark %d"] = "Искра %d"
L["Spark %d color"] = "Цвет искры %d"
L["a minute"] = "в минуту"
L["Swirl %d"] = "Вихрь %d"
L["Swirl %d color"] = "Цвет вихря %d"
L["Start distance"] = "Расстояние в начале"
L["Where it sits as the edges start to close in; bigger brings it nearer."] = "Где он стоит, когда края начинают сжиматься; больше — ближе."
L["Full distance"] = "Расстояние на максимуме"
L["Where it sits at full strength; its rim should frame the screen."] = "Где он стоит на полной силе; его край должен обрамлять экран."
L["The portal model's size, until /reload."] = "Размер модели портала, до /reload."
L["The theme's portal, its rim closing in around the screen as you weaken (no theme has one now)."] = "Портал темы, край которого смыкается вокруг экрана, пока вы слабеете (сейчас его нет ни у одной темы)."
L["Shadow reach, sides"] = "Охват тени по бокам"
L["Shadow color"] = "Цвет тени"
L["Beats as they start"] = "Удары в начале"
L["Beats a minute as the edges start to close in."] = "Ударов в минуту, когда края начинают сжиматься."
L["Beats at full"] = "Удары на максимуме"
L["Beats a minute at full."] = "Ударов в минуту на максимуме."
L["This theme's heartbeat speed, next to the beats above; a creeping theme beats slower."] = "Скорость сердцебиения этой темы относительно ударов выше; у ползучей темы сердце бьется медленнее."
L["How much this theme throbs, next to Throb above."] = "Насколько пульсирует эта тема относительно «Пульсации» выше."
L["Flash tint"] = "Оттенок вспышки"
L["Blizzard art"] = "Изображение Blizzard"
L["Cinematic art"] = "Изображение Cinematic"
L["Art color"] = "Цвет изображения"
L["Glow color"] = "Цвет свечения"
L["One of the game's own moving full-screen effects, closing in as you weaken over everything else."] = "Один из игровых подвижных эффектов на весь экран, который сжимается поверх всего, пока вы слабеете."
L["How strong it is at full, times the art's opacity."] = "Сила на максимуме, умноженная на непрозрачность изображения."
L["Where its edge sits: 50 is the game's, higher further in, lower past the screen."] = "Где проходит его край: 50 — как в игре, больше — ближе к центру, меньше — за краем экрана."
L["The card's style: its panel, face and emotes."] = "Стиль карточки: панель, лицо и эмоции."
L["The line around the card, in the Classic style."] = "Линия вокруг карточки в стиле «Классика»."
L["Above speech"] = "Над речью"
L["Just above the lines from behind you."] = "Прямо над репликами из-за спины."

