L["Card Vision is off: no card shows."] = "Card Vision выключена: карточки не показываются."
L["A small line low on the screen, where a movie's subtitles go."] = "Маленькая строка внизу экрана, где в кино идут субтитры."
L["The letters start spread apart and close up, like a movie title."] = "Буквы сначала разбросаны, а потом сходятся, как в титрах фильма."
L["In the middle of the screen, or low on it for a subtitle."] = "Посередине экрана или внизу, как субтитр."
