L["Buff/DoT"] = "Бафф/DoT"
L["Stay up while recharging"] = "Видно при перезарядке"
L["After combat"] = "После боя"
L["A ring around the icon that drains as your shield takes damage or its charges are used. Its look: Style > Cooldown Manager."] = "Кольцо вокруг значка, которое убывает, когда щит получает урон или тратятся заряды. Вид: Стиль > Менеджер восстановления."
L["What's left in the middle of the ring: the amount your shield can still absorb, or its charges."] = "Что в середине кольца: сколько щит еще может поглотить или сколько зарядов."
L["Shows only while the buff is off you, or off your target for a DoT."] = "Показывается, только пока баффа нет на вас, а для DoT — на цели."
L["Shows only while its buff is off you."] = "Показывается, только пока этого баффа нет на вас."
L["Missing: any"] = "Нет: любого"
L["Missing: any one"] = "Нет: хоть одного"
L["or %s"] = "или %s"
L["or %s +%d"] = "или %s +%d"
L["Where each icon shows, scene by scene."] = "Где показывается каждый значок, сцена за сценой."
L["Each icon's looks: countdown numbers, keybinds, flash."] = "Вид каждого значка: цифры отсчета, клавиши, вспышка."
L["Any place and time no scene covers. Faint: the same as the top row."] = "Любые место и время, которых нет ни в одной сцене. Бледное — как верхняя строка."
L["Click to edit this scene. Where scenes overlap, the one further left wins."] = "Нажмите, чтобы изменить эту сцену. Где сцены пересекаются, побеждает та, что левее."
L["See a place from anywhere: the grid shows what decides there, and your bars on screen act as if you were there."] = "Посмотрите на любое место откуда угодно: сетка покажет, что там решает, а ваши панели поведут себя так, будто вы там."
L["Tick spells to set them all at once, or copy one spell's row onto others."] = "Отметьте заклинания, чтобы настроить их разом, или скопируйте строку одного на другие."
L["Adds a scene: places and times, like dungeon fights, where icons can show differently."] = "Добавляет сцену: места и время (например, бои в подземельях), где значки могут показываться иначе."
L["Icons show the same in every scene"] = "Во всех сценах значки показываются одинаково"
L["Add a scene to make them differ in some places, like dungeons in combat."] = "Добавьте сцену, чтобы в каких-то местах было иначе, например в подземельях в бою."
L["+ Add scene"] = "+ Добавить сцену"
L["Its name. Leave it empty to name it by its rule."] = "Ее название. Оставьте пустым, чтобы назвать по ее правилу."
L["Moves this scene left. Where scenes overlap, the one further left wins."] = "Сдвигает сцену влево. Где сцены пересекаются, побеждает та, что левее."
L["Moves this scene right. Where scenes overlap, the one further left wins."] = "Сдвигает сцену вправо. Где сцены пересекаются, побеждает та, что левее."
L["Deletes this scene and what was set in it, on every tab."] = "Удаляет эту сцену и все, что в ней задано, на всех вкладках."
L["Renames this scene. Left empty, it's named by its rule."] = "Переименовывает сцену. Если оставить пустым, она называется по своему правилу."
L["Order"] = "Порядок"
L["In a fight (the Calm Timer after one too), out of one, or both."] = "В бою (и в таймер затишья после него), вне боя или оба."
L["Where this scene fits. Tick any number."] = "Где действует эта сцена. Отметьте сколько угодно."
L["Back to the dropdowns (the rule is dropped)."] = "Назад к спискам (правило сбросится)."
L["Tick spells to set them all at once, or to copy one onto others."] = "Отметьте заклинания, чтобы настроить их разом или скопировать одно на другие."
L["for every spell"] = "для всех заклинаний"
L["Every spell in %s does what this row says, unless you set it on its own."] = "Все заклинания в %s делают то, что говорит эта строка, если вы не настроили их отдельно."
