-- UI/RuleEditor.lua
L["Up and down to choose, Tab or Enter to take, Escape to close"] = "Вверх и вниз — выбрать, Tab или Enter — взять, Esc — закрыть"
L["Find a word"] = "Найти слово"
L["Searches every word by its name, what you'd type and what it means. Enter adds the first."] = "Ищет слова по названию, по тому, что вы бы ввели, и по смыслу. Enter добавляет первое."
L["Drops the rule, so the row's dropdowns decide again, ticked as they were before."] = "Убирает правило, и снова решают списки строки, отмеченные как раньше."
L["Both sides true. A word added after a word gets AND by itself."] = "Верны обе стороны. Между двумя словами AND ставится само."
L["Either side true. Right after an AND that was added for you, it takes its place."] = "Верна любая из сторон. Если поставить сразу после AND, добавленного за вас, встанет на его место."
L["The next word or brackets false. Shift-click a word to add it with NOT."] = "Следующее слово или скобки неверны. Shift+клик по слову добавит его с NOT."
L["Opens a group, around what you add next."] = "Открывает скобку вокруг того, что вы добавите дальше."
L["Closes the group."] = "Закрывает скобку."
L["Undoes the last change (Ctrl+Z)."] = "Отменяет последнее изменение (Ctrl+Z)."
L["Does it again (Ctrl+Y)."] = "Повторяет (Ctrl+Y)."
L["Nothing to pick here now"] = "Здесь сейчас нечего выбрать"
L["Opens a menu of what's here and what you have."] = "Открывает меню того, что здесь есть и что есть у вас."
L["True where you stand now."] = "Верно там, где вы сейчас."
L["False where you stand now."] = "Неверно там, где вы сейчас."
L["Click adds it; Shift-click adds NOT %s."] = "Клик добавляет его; Shift+клик добавляет NOT %s."
L["Words for \"%s\""] = "Слова для \"%s\""
L["%d found"] = "Найдено: %d"
L["No word matches. Try what it does: stun, buff, yards..."] = "Подходящих слов нет. Попробуйте по смыслу: оглушение, бафф, метры..."
