L["No new Zone or Subzone card for this long after one. Set to 0 to show one every time."] = "Столько времени после карточки зоны или подзоны новая не появится. 0 — показывать каждый раз."
L["The words as you go into a fight against players; leave empty for none."] = "Слова, когда вы вступаете в бой с игроками; оставьте пустым, чтобы их не было."
L["No card after fights shorter than this. Set to 0 for every fight."] = "Без карточки после боев короче этого. 0 — после каждого боя."
