L["Its usual card, in its own look (the Style tab)."] = "Обычная карточка в своем виде (вкладка «Стиль»)."
L["A picture in its own colors: red with a dark outline on a flat black band."] = "Картинка в своих цветах: красная с темной обводкой на ровной черной ленте."
L["Shows the line only this long at the start and end. All the way left (Off) shows it the whole way."] = "Показывает линию только столько в начале и в конце. До упора влево («Выкл.») — все время."

-- Visions/CombatSoundRules.lua
L["How loud the sounds are, compared to your sound effects volume."] = "Громкость звуков относительно громкости звуковых эффектов."
L["This sound's volume, compared to the others."] = "Громкость этого звука относительно остальных."
L["Resets this card's rules to the defaults."] = "Сбрасывает правила этой карточки к значениям по умолчанию."
L["Resets this tab to its default rules: one sound as any other fight starts and one as it ends."] = "Сбрасывает вкладку к правилам по умолчанию: один звук в начале любого другого боя и один в конце."

-- Visions/DamageVision.lua
L["Shows in every fight, wherever you are, so the other columns don't matter."] = "Видно в каждом бою, где бы вы ни были, так что остальные столбцы не важны."
L["Shows how you did on that boss as it dies."] = "Показывает, как вы сыграли на боссе, когда он погибает."
L["Shows how you did on the whole run once it's done."] = "Показывает, как вы сыграли за весь забег, когда он закончен."
L["Shows the recap card with the meter's whole run if you have one, or a made-up one if not (Stop hides it)."] = "Показывает итоговую карточку за весь забег из измерителя, если он есть, а если нет — выдуманную («Стоп» скрывает ее)."
L["Shows your place over it (#2)."] = "Показывает ваше место над ней (#2)."
L["A crown pops in as you take #1."] = "Когда вы выходите на #1, появляется корона."
L["Shows the name of the one you race, in their class's color."] = "Показывает имя соперника цветом его класса."
L["Shows your damage (or healing) so far."] = "Показывает ваш урон (или исцеление) на данный момент."
L["Shows each player's name on their row."] = "Показывает имя каждого игрока в его строке."
L["Amber while you're behind, teal once you lead, or two colors of your own."] = "Янтарный, пока вы отстаете, бирюзовый, когда впереди, или два своих цвета."

-- Visions/EmoteVision.lua
L["Emote Vision test: you'd %s."] = "Тест Emote Vision: вы бы %s."
L["Turn it on and pick which moments show a card, and the emotes on each."] = "Включите и выберите, в какие моменты показывать карточку и какие эмоции на каждой."
L["Cards that need the other player's nameplate. CineMode keeps it for them."] = "Карточки, которым нужен индикатор другого игрока. CineMode его для них сохраняет."
L["Puts the menu's emotes back to the defaults."] = "Возвращает эмоции меню к значениям по умолчанию."
L["Shows wherever you are, but never in a fight. A card that comes up in a fight waits for it to end."] = "Видно везде, но никогда в бою. Карточка, появившаяся в бою, подождет его конца."
L["Puts every moment's emotes back to the defaults."] = "Возвращает эмоции всех моментов к значениям по умолчанию."
L["Only buffs from strangers bring up a card, not buffs from your party or raid."] = "Карточку вызывают только баффы от незнакомцев, а не от вашей группы или рейда."

-- Page names and lists
L["A Minimap page in the Style hub: make the minimap square with a border in your theme's color, change its size, and hide its zoom buttons, zone bar or day and night dial."] = "Страница «Миникарта» в разделе «Стиль»: сделайте миникарту квадратной, с рамкой цвета вашей темы, поменяйте ее размер и спрячьте кнопки масштаба, полосу зоны или циферблат дня и ночи."
L["A boss down in a dungeon or raid with your group (each one, not just the last): the emotes go to everyone."] = "Ваша группа убила босса в подземелье или рейде (любого, не только последнего): эмоции уходят всем."
L["A boss's name as a title card, as its fight starts or as you first target it or come near: on the screen, in a letterbox bar or low on the left like a film, with its dungeon and which boss it is. Its look has its own tab on Battle Vision's Style page."] = "Имя босса как титр в кино — когда начинается бой, когда вы впервые берете его в цель или подходите близко: на экране, на полосе кадра или внизу слева, как в фильме, с подземельем и номером босса. Для его вида есть своя вкладка на странице стиля Battle Vision."
L["A buff of a minute or more someone else puts on you (Fortitude, Arcane Intellect, a blessing...). Not heals over time."] = "Бафф на минуту и дольше, который на вас наложил кто-то другой (Стойкость, Чародейский интеллект, благословение...). Не исцеление со временем."
L["A button on the inspect window opens the player's talents, and one on the talents window takes you back."] = "Кнопка в окне осмотра открывает таланты игрока, а кнопка в окне талантов возвращает обратно."
L["A calculator button on your talents window opens a talent planner that looks just like it, starting from your talents. Plan a build, see the level it needs, then copy it over to your talents window to apply."] = "Кнопка-калькулятор в окне талантов открывает планировщик, который выглядит так же и начинается с ваших талантов. Соберите билд, посмотрите, какой уровень нужен, и перенесите его в окно талантов, чтобы применить."
L["A cue as you go into a fight and come out of it: a word on the screen or in a letterbox bar, a pulse around the edges, an icon, and sounds you pick for each kind of fight, like horns for a raid boss. Its look has a page in the Style hub, with presets and a preview."] = "Сигнал при входе в бой и выходе из него: слово на экране или на полосе кадра, пульс по краям, значок и звуки, которые вы выберете для каждого вида боя, например рог для рейдового босса. Для его вида есть страница в разделе «Стиль», с наборами и предпросмотром."
L["A grid that shows or hides each part of the nameplates in CineMode: health bar, name, cast bar, buffs, level and more."] = "Сетка, которая показывает или скрывает каждую часть индикаторов в CineMode: полосу здоровья, имя, полосу заклинаний, баффы, уровень и другое."
L["A mark on your target's nameplate for when no target frame shows who you've got: an arrow, chevron, glow or brackets, colored by how they see you."] = "Метка на индикаторе цели, когда рамки цели не видно: стрелка, шеврон, свечение или скобки, цветом по отношению цели к вам."
L["A new Retail profile gives WoW Forever retail's look: Cinematic's own Edit Mode layout, with action bars 1 to 3, the micro menu and bags, and the XP bar each coming up on its own. Switch back to Default and your own layout returns."] = "Новый профиль Retail дает WoW Forever вид Retail: собственный макет редактора режимов от Cinematic, где панели команд 1–3, микроменю с сумками и полоса опыта появляются каждая сама по себе. Вернитесь на «По умолчанию», и ваш макет вернется."
L["A new Spells tab on Combat Text Style gives any of your spells its own color, size and look, its crits and DoT ticks too."] = "Новая вкладка «Заклинания» в «Стиле текста боя» дает любому вашему заклинанию свой цвет, размер и вид, и его критам и тикам DoT тоже."
L["A new Vision for the words that fade in on your screen between fights: what you did last time as you log in (\"Last time: Darkshore · 3 quests done · reached level 24\"), the time of day, a place under attack, and the death banner, each with its own tick and a Test button. Combat Vision is now called Battle Vision."] = "Новая Vision для слов, которые проявляются на экране между боями: что вы делали в прошлый раз, когда входите в игру (\"В прошлый раз: Темные берега · 3 задания выполнено · достигнут 24 уровень\"), время суток, место под атакой и надпись при смерти — у каждого своя отметка и кнопка «Тест». Combat Vision теперь называется Battle Vision."
L["A new Wheels page shows every wheel and its icons, with its keybind right there, and lets you pick which wheels sit on the master wheel and in what order."] = "Новая страница «Колеса» показывает все колеса и их значки вместе с клавишами и дает выбрать, какие колеса будут на главном колесе и в каком порядке."
L["A new page in the Community hub with links to the Discord, YouTube, CurseForge and GitHub, ready to copy."] = "Новая страница в разделе «Сообщество» со ссылками на Discord, YouTube, CurseForge и GitHub, готовыми к копированию."
L["A new rule editor"] = "Новый редактор правил"
L["A place new to you: a zone the first time you're there, a subzone as the game says you discovered it, a dungeon or raid the first time you go in. In place of the Zone or Subzone card."] = "Новое для вас место: зона, когда вы там впервые, подзона, когда игра сообщает, что вы ее открыли, подземелье или рейд при первом входе. Вместо карточки зоны или подзоны."
L["A track with you above it and your rival below; the gap between you in color."] = "Дорожка: вы сверху, соперник снизу, а разрыв между вами — цветом."
L["After an update with new features, a line in chat at login says so, with a link to What's new. Turn it off on the Chat page."] = "После обновления с новыми функциями при входе в чате появится строка об этом со ссылкой на «Что нового». Выключается на странице «Чат»."
L["An over-the-shoulder camera: you sit to one side of the screen and stay there as you zoom. Swap shoulders with a key, turn toward the NPCs you talk to and the enemies you target, and let your cast bar and resources slide along with you."] = "Камера через плечо: вы стоите сбоку экрана и остаетесь там при любом приближении. Меняйте плечо клавишей, поворачивайтесь к НИП, с которыми говорите, и к врагам в цели, а полоса заклинаний и ресурсы пусть едут вместе с вами."
L["Arcane stars"] = "Чародейские звезды"
L["As a dungeon's or raid's last boss goes down: its name, the time since you came in and how many times you died."] = "Когда падает последний босс подземелья или рейда: его название, время с момента входа и сколько раз вы умерли."
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal opens around you in your class and spec's color, closing in as the cast fills, then the screen goes black as you're whisked away. It plays alongside the tele camera."] = "Когда вы используете камень возвращения, Астральное возвращение или телепорт, вокруг вас открывается портал цвета вашего класса и специализации и смыкается по мере заклинания, а потом экран темнеет и вас уносит. Играет вместе с камерой телепорта."
L["As you come into an inn or a city (not at login, not in a fight): the place's name. The same place at most once every 10 minutes."] = "Когда вы заходите в таверну или город (не при входе в игру и не в бою): название места. Одно и то же место — не чаще раза в 10 минут."
L["As you reach a new level (after the fight, if you're in one): the level, the zone and how long it took this session. Max level at the cap."] = "Когда вы получаете новый уровень (после боя, если вы в бою): уровень, зона и сколько времени это заняло за сеанс. На последнем уровне — «Максимальный уровень»."
L["As you turn in a story quest (campaign, important or legendary) or a dungeon, raid or elite one: its title."] = "Когда вы сдаете сюжетное задание (кампании, важное или легендарное) или задание подземелья, рейда или элитное: его название."
L["As your health drops, dark edges creep in around the screen with art themed to your class and talents (blood, frost, fire...), a heartbeat that quickens and a flash on big hits, so you can tell how you're doing at a glance."] = "Когда здоровье падает, по краям экрана наползает темнота с изображением в духе вашего класса и талантов (кровь, лед, огонь...), учащается сердцебиение, а сильные удары дают вспышку — с одного взгляда ясно, как у вас дела."
L["At an NPC"] = "У НИП"
L["BigWigs, TomTom, HealBot Continued and Titan Panel get rows of their own and fade with Cinematic. Platynator and Threat Plates nameplates fade in CineMode, and Prat 3.0's chat follows the Chat page."] = "У BigWigs, TomTom, HealBot Continued и Titan Panel свои строки, и они скрываются вместе с Cinematic. Индикаторы Platynator и Threat Plates скрываются в CineMode, а чат Prat 3.0 слушается страницы «Чат»."
L["Blood mist"] = "Кровавый туман"
L["Camera Modes and Camera Triggers are now one Cameras page: a row for each trigger (an emote, a campfire, going AFK, a flight...) with the camera it starts, its music and CineMode, and where it can start. Copy a row to give a trigger a different camera in other places."] = "«Режимы камеры» и «Триггеры камеры» теперь одна страница «Камеры»: строка на каждый триггер (эмоция, костер, уход в АФК, полет...) с камерой, которую он запускает, музыкой, CineMode и тем, где он может сработать. Скопируйте строку, чтобы в других местах у триггера была другая камера."
L["Change any Vitals Vision theme's art, colors, sparks and heartbeat, or make themes of your own from one, and rename or delete them. Reset theme puts one of ours back as it comes."] = "Меняйте изображение, цвета, искры и сердцебиение любой темы Vitals Vision или делайте на ее основе свои темы, переименовывайте и удаляйте их. «Сбросить тему» возвращает нашу тему в исходный вид."
L["ClassicUI Forever's action bars, bar art and quest watch now fade with Cinematic, and come back when you hover them."] = "Панели команд, оформление панелей и список заданий ClassicUI Forever теперь скрываются вместе с Cinematic и появляются при наведении."
L["Click the star beside any settings page's search box to save that page, open at the tab you're on. Your favorites get their own line at the top of Cinematic's list."] = "Нажмите на звездочку у поиска на любой странице настроек, чтобы сохранить ее открытой на текущей вкладке. У избранного своя строка вверху списка Cinematic."
L["Combat text by spell"] = "Текст боя по заклинаниям"
L["Cooldown Manager grid"] = "Сетка менеджера восстановления"
L["Creeping shadow"] = "Ползучая тень"
L["Ctrl+Click an auction to see it on your character in a small dressing room beside the Auction House, which now stays open. Turn it on in Quality of Life."] = "Ctrl+клик по лоту — и он появится на вашем персонаже в маленькой примерочной рядом с аукционом, а аукцион останется открытым. Включается в «Удобстве»."
L["Dressing room at the Auction House"] = "Примерочная на аукционе"
L["Earth wisps"] = "Огоньки земли"
L["ElvUI's frames, Deadly Boss Mods' timer bars and RestedXP's guide window now fade in CineMode: ElvUI's following the Game Frames rows of the frames they replace, RestedXP's with the Quest tracker row."] = "Рамки ElvUI, полосы таймеров Deadly Boss Mods и окно гайда RestedXP теперь скрываются в CineMode: ElvUI — по строкам «Рамок игры» тех рамок, которые заменяет, RestedXP — со строкой «Список заданий»."
L["Embers"] = "Угольки"
L["Every camera is now a script of steps (turn, zoom, sway, wait, follow...) on the new Scripts page in the Camera hub. Pick one to see how it moves, change its steps and settings there, or copy it to make a camera of your own."] = "Каждая камера теперь — сценарий из шагов (поворот, приближение, покачивание, ожидание, следование...) на новой странице «Сценарии» в разделе «Камера». Выберите любую, чтобы увидеть, как она движется, поменяйте шаги и настройки или скопируйте, чтобы сделать свою камеру."
L["Every grid now has the same row: Always, then Combat, Target and Location dropdowns, Roles and Edit. Edit turns a row into a rule, for AND, NOT, Cities and more, with a dot showing whether it's on right now. Chat bubbles, tooltips, effects, music and the cameras now say where they show instead of where they hide."] = "Во всех сетках теперь одна и та же строка: «Всегда», потом списки «Бой», «Цель» и «Местоположение», «Роли» и «Изменить». «Изменить» превращает строку в правило — для AND, NOT, «Городов» и прочего, а точка показывает, включено ли оно прямо сейчас. Облачка чата, подсказки, эффекты, музыка и камеры теперь говорят, где они видны, а не где скрыты."
L["Fel wisps"] = "Огоньки Скверны"
L["FlareUI's unit frames, resource bars, buffs, quest tracker, party and raid frames fade in CineMode, following the Game Frames rows of the frames they replace."] = "Рамки юнитов, полосы ресурсов, баффы, список заданий, рамки группы и рейда FlareUI скрываются в CineMode по строкам «Рамок игры» тех рамок, которые заменяют."
L["Frames Forever's unit frames follow the Game Frames rows of the frames they replace. ShamanPower's totem bar fades with the Totem bar row, and its cooldown bar gets a row of its own."] = "Рамки юнитов Frames Forever слушаются строк «Рамок игры» тех рамок, которые заменяют. Панель тотемов ShamanPower скрывается со строкой «Панель тотемов», а у ее полосы восстановления своя строка."
L["Frost creeps in on the screen's edges in snow, rain runs down the lens, and lightning flashes with thunder in storms. Off to start with: turn each up on the Weather page."] = "В снег по краям экрана ползет иней, в дождь по объективу бегут капли, а в грозу сверкают молнии и гремит гром. Поначалу выключено: включите каждое на странице «Погода»."
L["Gliding"] = "Парение"
L["Green wisps"] = "Зеленые огоньки"
L["Guidelime support"] = "Поддержка Guidelime"
L["Guidelime's guide window, its ongoing steps and its waypoint arrow get a row each, so you can hide the guide and keep the arrow pointing the way."] = "У окна гайда Guidelime, текущих шагов и стрелки к точке маршрута по своей строке — можно спрятать гайд и оставить стрелку, чтобы она показывала путь."
L["Hold a key to bring up a wheel of raid markers and put one on your target, or drop a ground marker where you let go. A master wheel opens any of the wheels from one key. Set the keys on the Keybinds page."] = "Удерживайте клавишу, чтобы вызвать колесо рейдовых меток и поставить метку на цель, или бросьте метку на землю там, где отпустите. Главное колесо открывает любое колесо одной клавишей. Клавиши — на странице «Клавиши»."
L["Hold a key to bring up a wheel of the visions and turn Heal, Quest, Duel or Roll Vision on or off, even in a fight. It's on the master wheel too, and each vision has a toggle key of its own on the Keybinds page."] = "Удерживайте клавишу, чтобы вызвать колесо Visions и включать или выключать Heal, Quest, Duel или Roll Vision, даже в бою. Оно есть и на главном колесе, а у каждой Vision своя клавиша на странице «Клавиши»."
L["In CineMode the two players in a duel near you get their nameplates, each duel with its own color border and class icons."] = "В CineMode у двух игроков, которые дерутся на дуэли рядом с вами, появляются индикаторы, у каждой дуэли своя цветная рамка и значки классов."
L["In a group, a window shows each item being rolled on, with everyone's pick and roll and the winner on top, so you needn't read the rolls in chat. Turn it off in the Visions page."] = "В группе окно показывает каждый разыгрываемый предмет, выбор и бросок каждого, а победитель сверху — не нужно читать броски в чате. Выключается на странице Visions."
L["Instead of damage meter numbers, see your race with #1 (or your lead over #2) as a bar, a race track or a ladder, plus a recap of how you did after each boss and dungeon."] = "Вместо цифр измерителя урона — ваша гонка с #1 (или отрыв от #2) в виде полосы, беговой дорожки или лесенки, а еще итоги после каждого босса и подземелья."
L["Interface, Camera and Quality of life hold their pages behind a row of icons, with one search box for all of them."] = "У «Интерфейса», «Камеры» и «Удобства» страницы спрятаны за рядом значков, с одним поиском на всех."
L["Jade wisps"] = "Нефритовые огоньки"
L["Links to the guidebook, troubleshooting and the bug report form, how to send your log with /cine log, and the Profiler for a slow game, together in Community."] = "Ссылки на руководство, решение проблем и форму для сообщения об ошибке, как отправить журнал через /cine log и профилировщик, если игра тормозит, — все вместе в «Сообществе»."
L["Lore Forever's subtitles, floating player, new page note and pin card get rows of their own and fade with Cinematic. With Custom dialogue frames on, a Play button on the box with the NPC's words plays the quest's narration or stops it."] = "У субтитров, плавающего плеера, заметки о новой странице и карточки метки Lore Forever свои строки, и они скрываются вместе с Cinematic. Если включены «Свои окна диалога», кнопка воспроизведения в окне с речью НИП включает или останавливает озвучку задания."
L["Make scenes, like dungeons in combat, and pick what each spell shows in each one, side by side in one grid. Tick several spells to set them at once, or copy one spell's row onto others."] = "Создавайте сцены, например «подземелья в бою», и выбирайте, что показывает каждое заклинание в каждой, — все рядом в одной сетке. Отметьте несколько заклинаний, чтобы настроить их разом, или скопируйте строку одного на другие."
L["Make your own camera scenes on the Scenes page: an emote, a spell, a buff, a place, a moment or a key can start one, and a scene can have several triggers. The built-in ones are grouped by camera and take triggers of yours too. On My Shots, set how a camera sways and zooms, and share either with a friend."] = "Создавайте свои сцены камеры на странице «Сцены»: запустить сцену может эмоция, заклинание, бафф, место, момент или клавиша, а у сцены может быть несколько триггеров. Встроенные сгруппированы по камерам и тоже принимают ваши триггеры. В «Моих кадрах» настройте, как камера покачивается и приближается, и делитесь тем и другим с друзьями."
L["Marks and colors for your focus, the unit under the mouse and a target that's attacking you, not just your target, each with its own look, when it shows, and rows for just enemies or friends. Set them on the Style hub's Nameplates page."] = "Метки и цвета не только для цели, но и для фокуса, того, кто под курсором, и цели, которая атакует вас, — у каждого свой вид, свое время показа и строки отдельно для врагов или друзей. Настраиваются на странице «Индикаторы» в разделе «Стиль»."
L["Mobs and NPCs you still need for a quest keep their nameplates up, with a golden ! on their plate and your target frame. Optionally, the quest object in front of you glows so it's easy to spot."] = "Монстры и НИП, которые еще нужны для задания, сохраняют индикаторы с золотым ! на индикаторе и на рамке цели. По желанию предмет задания перед вами светится, чтобы его было легко заметить."
L["Motes (class and spec)"] = "Пылинки (класс и специализация)"
L["Motes of light"] = "Пылинки света"
L["Nameplates have a hub of their own: which show, the new Icons page for class and role icons, and their looks. Each kind of plate can have its own parts, and each Nameplate Style row its own bar, border, name font and level box."] = "У индикаторов теперь свой раздел: какие показывать, новая страница «Значки» для значков классов и ролей и их вид. У каждого типа индикаторов могут быть свои части, а у каждой строки «Стиля индикаторов» — своя полоса, рамка, шрифт имени и рамка уровня."
L["Names kept up over faded nameplates in CineMode now look like the game's own names over heads: colored by who they are, and smaller further off."] = "Имена, которые остаются над скрытыми индикаторами в CineMode, теперь выглядят как игровые имена над головами: цвет по тому, кто это, и мельче вдалеке."
L["Naowh Forever's top bar now fades in CineMode (a row on the Addon Frames page), and its RestedXP guide window fades with the Quest tracker row."] = "Верхняя панель Naowh Forever теперь скрывается в CineMode (строка на странице «Рамки аддонов»), а ее окно гайда RestedXP скрывается со строкой «Список заданий»."
L["Pick HD or SD for Cinematic's settings and windows on the main page: flat and dark, or the game's own look. Auto follows your client, and your Character Models setting on WoW Forever."] = "Выберите HD или SD для настроек и окон Cinematic на главной странице: плоский темный вид или вид самой игры. «Авто» следует вашему клиенту, а на WoW Forever — настройке моделей персонажей."
L["Pick how much Cinematic does, Subtle, Balanced or Cinema, then Customize changes one part at a time: your layout, camera, look, Visions, chat and sound."] = "Выберите, насколько много делает Cinematic: «Легкий», «Сбалансированный» или «Кино», а «Настроить» меняет по одной части: макет, камеру, вид, Visions, чат и звук."
L["Pick which parts of your frame and the target and focus frames show (portrait, name, level, frame art) for you and each kind of unit, to keep just the bars."] = "Выберите, какие части вашей рамки и рамок цели и фокуса показывать (портрет, имя, уровень, оформление) для вас и каждого типа юнитов, — можно оставить одни полосы."
L["Plague wisps"] = "Чумные огоньки"
L["Pretends you're auto-running: the auto-run camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Изображает автобег: камера автобега работает 30 секунд, пока вы стоите на месте. Если сдвинуться или нажать «Стоп», она закончится."
L["Pretends you're auto-walking: the RP walk camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Изображает автоходьбу: камера РП-шага работает 30 секунд, пока вы стоите на месте. Если сдвинуться или нажать «Стоп», она закончится."
L["Rain"] = "Дождь"
L["Rain, snow and sandstorms have their own page in Atmosphere. Preview each one, and pick its color and how fast it comes in on the Style tab."] = "У дождя, снега и песчаных бурь своя страница в «Атмосфере». Посмотрите каждую погоду, а на вкладке «Стиль» выберите ее цвет и как быстро она наступает."
L["Runs Chat Cam for 30 seconds with a made-up conversation between two speakers either side of you. Moving, or clicking Stop, ends it."] = "Запускает камеру чата на 30 секунд с выдуманным разговором двух собеседников по обе стороны от вас. Если сдвинуться или нажать «Стоп», она закончится."
L["Runs the quest camera for 30 seconds as if you were talking to a quest giver in front of you. Moving, or clicking Stop, ends it."] = "Запускает камеру заданий на 30 секунд, будто вы говорите с тем, кто дает задание, прямо перед вами. Если сдвинуться или нажать «Стоп», она закончится."
L["Sea breeze"] = "Морской бриз"
L["See how much of your computer's time Cinematic takes, as a graph of the last five minutes, and record a while of play to see which parts cost the most. If Cinematic feels slow, Copy report and send it to us."] = "Посмотрите, сколько времени компьютера занимает Cinematic, на графике за последние пять минут, и запишите немного игры, чтобы увидеть, какие части тяжелее всего. Если Cinematic тормозит, нажмите «Копировать отчет» и пришлите нам."
L["See your keyboard on screen with what every key does: its spell's icon, cooldown and count, or the command's name. Hold its key to peek, tap it to keep it up, or type /cine keys. Hold Shift, Ctrl or Alt to see those keys."] = "Клавиатура на экране и что делает каждая клавиша: значок заклинания, восстановление и количество или название команды. Удерживайте ее клавишу, чтобы взглянуть, нажмите, чтобы оставить на экране, или введите /cine keys. Удерживайте Shift, Ctrl или Alt, чтобы увидеть эти сочетания."
L["Share a wheel of yours as a line of text and import one from a friend, reading every command first. Icons now come from every icon the game has, like the macro window's, and you can add icons of your own to the marker and vision wheels."] = "Делитесь своим колесом в виде строки текста и импортируйте колеса друзей, сначала прочитав каждую команду. Значки теперь можно брать из всех значков игры, как в окне макросов, а на колеса меток и Visions — добавлять свои."
L["Shortly after the death camera starts: YOU DIED across the middle of the screen, \"wasted\" or words of your own. Only with the death camera on (the Die row on the Scenes page)."] = "Вскоре после начала камеры смерти: ВЫ ПОГИБЛИ через весь экран, \"потрачено\" или ваши слова. Только с включенной камерой смерти (строка «Смерть» на странице «Сцены»)."
L["Shows a pretend card for each moment in turn (close the settings to see it). With someone targeted it's theirs, and its buttons really emote at them; with no one, they only say in chat what they'd do."] = "Показывает по очереди пробную карточку для каждого момента (закройте настройки, чтобы увидеть). Если кто-то в цели, карточка от него, и кнопки правда отправляют ему эмоции; если никого — только пишут в чат, что бы сделали."
L["Six new Vitals Vision themes are built from the game's own full-screen effects, moving and closing in as your health drops: Cosmic void, Hellfire, Radiance, Frostbite, Fel flames and Spellfire. Find them under More themes."] = "Шесть новых тем Vitals Vision из игровых эффектов на весь экран, которые двигаются и сжимаются, когда падает здоровье: «Космическая пустота», «Адское пламя», «Сияние», «Обморожение», «Пламя Скверны» и «Чародейский огонь». Ищите их в «Еще темы»."
L["Someone from your guild (not in your group) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Кто-то из вашей гильдии (не в группе) попадает в поле зрения: с включенными дружественными индикаторами — как только вы его увидите, иначе — когда наведете курсор или возьмете в цель. Раз в час на человека."
L["Someone near you earns an achievement (a stranger, someone in your group or in your guild)."] = "Кто-то рядом получает достижение (незнакомец, кто-то из группы или гильдии)."
L["Someone you grouped with lately (the game's Recent Allies, not in your group now) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Кто-то, с кем вы недавно были в группе («Недавние союзники» в игре, сейчас не в группе), попадает в поле зрения: с включенными дружественными индикаторами — как только вы его увидите, иначе — когда наведете курсор или возьмете в цель. Раз в час на человека."
L["Souls"] = "Души"
L["Spanish, German, French, Russian, Portuguese, Italian, Korean and Chinese, with a Language choice on the main page."] = "Испанский, немецкий, французский, русский, португальский, итальянский, корейский и китайский, с выбором языка на главной странице."
L["Starlight"] = "Звездный свет"
L["Talking to an NPC, their words show in a speech bubble over their head and your replies in a list below, instead of the game's gossip and quest windows. Pick a reply with 1-9, and Space to read on."] = "Когда вы говорите с НИП, его слова появляются в облачке над головой, а ваши ответы — списком ниже, вместо игровых окон разговора и заданий. Ответ выбирается клавишами 1-9, а пробел листает дальше."
L["The Addon Frames page's Find frames tab can look for other addons' frames that nothing fades, say which addon made each and guess which row it should follow. Add them with a click."] = "Вкладка «Найти рамки» на странице «Рамки аддонов» умеет искать рамки других модификаций, которые никто не скрывает, говорить, чья это рамка, и угадывать, какой строке она должна следовать. Добавляются одним кликом."
L["The Camera hub's General page now shows every camera, built in and yours, as an icon. Click one to open a tab with its script and the scenes that play it, and jump straight to either."] = "Страница «Общие» в разделе «Камера» теперь показывает каждую камеру, встроенную и вашу, значком. Нажмите на любую, чтобы открыть вкладку с ее сценарием и сценами, которые ее играют, и сразу перейти к ним."
L["The Cards page has 13 new moments: level up, places discovered, flight arrivals, inns, achievements, reputation, new mounts and pets, profession ranks, story quests, dungeons cleared, rares, battlegrounds and kill streaks. Every card now belongs to one of four looks, so they match out of the box."] = "На странице «Карточки» 13 новых моментов: новый уровень, открытые места, прилет, таверны, достижения, репутация, новые транспорт и питомцы, ранги профессий, сюжетные задания, пройденные подземелья, редкие, поля боя и серии убийств. Каждая карточка теперь в одном из четырех видов, так что все сразу сочетаются."
L["The UI fades and letterbox bars come in between fights. Combat, casting and opening windows bring it back."] = "Между боями интерфейс исчезает и появляются полосы кадра. Бой, заклинания и открытые окна возвращают его."
L["The faded minimap comes up when ore, herbs or treasure show on it, a quest of yours is done, or another icon appears, with a ping on the node if you like."] = "Скрытая миникарта появляется, когда на ней видна руда, травы или сокровища, задание выполнено или появился другой значок, — по желанию с сигналом на точке."
L["The first time you enter a zone like Westfall or Duskwood, its name slams onto the screen in huge white capitals. Comes with the new Headline style."] = "Когда вы впервые входите в зону вроде Западного Края или Сумеречного леса, ее название с размаху появляется на экране огромными белыми буквами. Идет с новым стилем «Заголовок»."
L["The game's floating combat text about you (hits, heals, misses, power, auras, Low Health) now has a page of its own on Style: a look for each kind, beside your character, and it can follow the Shoulder Cam."] = "У игрового всплывающего текста боя о вас (удары, исцеление, промахи, ресурс, ауры, мало здоровья) теперь своя страница в «Стиле»: свой вид для каждого типа, рядом с персонажем, и он может следовать за камерой через плечо."
L["The game's own graphics settings one by one, past what its Graphics menu allows: ground clutter, view distance and more."] = "Настройки графики самой игры по одной, дальше, чем позволяет ее меню «Графика»: мелкие объекты, дальность обзора и другое."
L["The game's windows open in the middle of the screen, can be dragged by their title bar and open where you last dropped them. The backpack too."] = "Окна игры открываются посередине экрана, их можно перетаскивать за заголовок, и они открываются там, где вы их оставили. Рюкзак тоже."
L["The minimap button glows while a vision is doing something, and its menu lists the visions in use with a link to each one's page."] = "Кнопка у миникарты светится, пока какая-то Vision что-то делает, а в ее меню — список работающих Visions со ссылкой на страницу каждой."
L["The names Cinematic draws on faded nameplates in CineMode have a page of their own: their colors, outline, opacity, size and height, with presets and a preview."] = "У имен, которые Cinematic рисует на скрытых индикаторах в CineMode, своя страница: цвета, обводка, прозрачность, размер и высота, с наборами и предпросмотром."
L["The rule editor is rebuilt: words in categories you can search, suggestions as you type, and a line that shows which parts of your rule are true where you stand."] = "Редактор правил переделан: слова разложены по категориям с поиском, подсказки появляются по ходу ввода, а строка показывает, какие части правила верны там, где вы стоите."
L["Three new cards in the top bar: how much of a zone you've explored, an achievement with one step left, and an achievement's step done. Each shows at most once every 10 minutes; on in the Cinema profile."] = "Три новые карточки в верхней полосе: сколько зоны вы исследовали, достижение, до которого остался один шаг, и выполненный шаг достижения. Каждая не чаще раза в 10 минут; включены в профиле «Кино»."
L["Tick Copy chat button on the Quality of life page and a small icon in a chat window's corner opens its lines, ready to select and copy with Ctrl+C."] = "Отметьте «Кнопка копирования чата» на странице «Удобство», и маленький значок в углу окна чата откроет его строки, чтобы выделить и скопировать через Ctrl+C."
L["Tick Show speech from behind you on the Chat page and says and yells from people behind you or out of view show as bubbles low on the screen, rising up from below, instead of bringing up chat."] = "Отметьте «Показывать речь из-за спины» на странице «Чат», и реплики и крики тех, кто у вас за спиной или вне поля зрения, будут всплывать облачками снизу экрана, а не открывать чат."
L["Type /cine find and a few words, or search in the settings, to get a list of every matching option; click one to go straight to it."] = "Введите /cine find и пару слов или воспользуйтесь поиском в настройках — и получите список всех подходящих параметров; нажмите на любой, чтобы сразу к нему перейти."
L["Type /cine why, or pick it from the minimap button's menu, then click any frame to see why it's showing or hidden right now and which settings say so. It works on other addons' frames, Cinematic's own (like quest talk), and the last tooltip too. The Why Is It Showing? page in Community lists every row of frames at once."] = "Введите /cine why или выберите это в меню кнопки у миникарты, потом нажмите на любую рамку — и узнаете, почему она сейчас видна или скрыта и какие настройки так решили. Работает с рамками других модификаций, с рамками самого Cinematic (например, диалогами заданий) и с последней подсказкой. Страница «Почему это видно?» в «Сообществе» показывает все строки рамок сразу."
L["Type part of a frame's name, or of the addon that made it, to find frames to fade. Hover a match to see it marked on screen, then click it to fade it."] = "Введите часть названия рамки или модификации, которая ее создала, чтобы найти рамки для скрытия. Наведите на совпадение, чтобы увидеть его на экране, и нажмите, чтобы скрыть."
L["Valhalla"] = "Вальхалла"
L["Venom wisps"] = "Ядовитые огоньки"
L["Vitals Vision's themes now have spiral arms turning over the screen as your health drops, quicker the weaker you are. Set them on the Style page's new Swirl tab, or try the swirl themes under More themes: Vortex, Abyss and Dungeon portal."] = "В темах Vitals Vision теперь есть спиральные рукава, которые вращаются по экрану, когда падает здоровье, — тем быстрее, чем вы слабее. Настраиваются на новой вкладке «Вихрь» страницы стиля, или попробуйте вихревые темы в «Еще темы»: «Воронка», «Бездна» и «Портал подземелья»."
L["Weather on the screen"] = "Погода на экране"
L["Weather page"] = "Страница погоды"
L["Wheels of your own, up to 8: each icon on one runs a command when you pick it, such as /rw Pull in 10 or /readycheck (anything a macro can do, a line each), in a fight too. Give a wheel its own key here, or put it on the master wheel. They're the same for all your characters."] = "Свои колеса, до 8: каждый значок на колесе запускает команду, когда вы его выбираете, например /rw Пул через 10 или /readycheck (все, что умеет макрос, по строке на команду), и в бою тоже. Дайте колесу свою клавишу здесь или поставьте его на главное колесо. Они общие для всех ваших персонажей."
L["When someone buffs you, raises you, emotes at you, summons you or trades with you, or your group kills a boss or levels up, a small card shows who it was, with emotes to answer in one click. Pick each moment's emotes (voice ones too) and one of six card styles."] = "Когда вас баффают, воскрешают, призывают, отправляют вам эмоцию или предлагают обмен, или ваша группа убивает босса или получает уровень, маленькая карточка показывает, кто это был, с эмоциями для ответа в один клик. Выберите эмоции для каждого момента (и голосовые тоже) и один из шести стилей карточки."
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), with your faction's city bell. The same place at most once every 90 seconds."] = "Когда канал «Оборона» сообщает, что место атаковано (\"Дун Альгаз атакован!\"), — под колокол столицы вашей фракции. Одно и то же место — не чаще раза в 90 секунд."
L["When the time of day changes during play (not in combat), its name with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "Когда во время игры меняется время суток (не в бою), его название с подходящим звуком: петух на рассвете, лошадь утром, колокол вашей фракции в полдень, лягушки вечером, сова в сумерках и волк ночью."
L["Wisps"] = "Огоньки"
L["Wisps (class and spec)"] = "Огоньки (класс и специализация)"
L["You and a stranger (not in your group or guild) target each other for 10 seconds straight. Once you've looked away, it can happen again."] = "Вы и незнакомец (не из группы и не из гильдии) 10 секунд подряд держите друг друга в цели. Когда вы отвернетесь, это может случиться снова."
L["Your character lies down as if dead and the death camera runs for 30 seconds. Moving, or clicking Stop, ends it."] = "Ваш персонаж ложится, будто мертвый, и камера смерти работает 30 секунд. Если сдвинуться или нажать «Стоп», она закончится."
L["Your player frame, pet frame and resource display have a page of their own: kept up while you recover or run low on mana, and held back at the start of a fight until your power changes."] = "У вашей рамки игрока, рамки питомца и показа ресурсов своя страница: они видны, пока вы восстанавливаетесь или у вас мало маны, и не появляются в начале боя, пока не изменится ресурс."
L["\"Dun Algaz is under attack!\" shows in red where the zone name appears, with your faction's city bell."] = "\"Дун Альгаз атакован!\" появляется красным там, где обычно название зоны, под колокол столицы вашей фракции."
L["combat"] = "бой"
